/**
 * Standard HTTP Request representation for the backend router (INFRA-02 Step 04, INFRA-03 Step 01 & Step 03).
 */
data class HttpRequest(
    val method: String,
    val path: String,
    val headers: Map<String, String> = emptyMap(),
    val body: Any? = null,
    val clientIp: String = "127.0.0.1"
) {
    val authorizationHeader: String? get() = headers.entries.find { it.key.equals("Authorization", ignoreCase = true) }?.value
    val idempotencyKey: String? get() = headers.entries.find { it.key.equals("Idempotency-Key", ignoreCase = true) }?.value
    val correlationId: String get() = com.sucharu.sucharupro.data.observability.correlation.CorrelationIdGenerator.normalizeOrGenerate(headers.entries.find { it.key.equals("X-Correlation-ID", ignoreCase = true) }?.value)
}

/**
 * Standard HTTP Response representation.
 */
data class HttpResponse(
    val statusCode: Int,
    val body: Any,
    val correlationId: String
)

/**
 * Server-side REST API Router and Request Dispatcher (INFRA-02 Step 04, INFRA-03 Step 01 & Step 03, INFRA-05 Step 06).
 */
class BackendRouter(
    private val securityContext: BackendSecurityContext,
    private val useCases: BackendUseCases,
    private val healthChecker: DatabaseHealthChecker,
    private val rateLimiter: BackendRateLimiter = BackendRateLimiter(),
    private val authService: AuthenticationService? = null,
    private val userIdentityService: UserIdentityService? = null,
    private val workflowControlPlaneService: com.sucharu.sucharupro.data.workflow.control.WorkflowControlPlaneService? = null,
    private val webhookIngressService: com.sucharu.sucharupro.data.integration.service.WebhookIngressService? = null,
    private val metricsRegistry: com.sucharu.sucharupro.data.observability.metrics.ObservabilityMetricsRegistry? = null,
    private val healthRegistry: com.sucharu.sucharupro.data.observability.health.HealthRegistry? = null,
    private val securityEventRecorder: com.sucharu.sucharupro.data.observability.event.SecurityEventRecorder? = null,
    private val operationalEventRecorder: com.sucharu.sucharupro.data.observability.event.OperationalEventRecorder? = null,
    private val slowRequestThresholdMs: Long = 1000L
) {

    suspend fun handleRequest(request: HttpRequest): HttpResponse {
        val startTime = System.currentTimeMillis()
        val correlationId = request.correlationId

        val response = try {
            // 1. Rate Limiting Check
            rateLimiter.checkRateLimit(request.clientIp)

            // 2. Route Dispatch
            when {
                // Health Probes (Supports /health, /health/live, /health/liveness)
                (request.path == "/health" || request.path == "/health/live" || request.path == "/health/liveness") && request.method == "GET" -> {
                    val isLive = healthRegistry?.evaluateLiveness() ?: healthChecker.checkLiveness()
                    HttpResponse(200, ApiSuccessResponse(data = mapOf("status" to if (isLive) "UP" else "DOWN", "service" to "sucharu-server"), correlationId = correlationId), correlationId)
                }

                // Readiness Probes (Supports /ready, /health/ready, /health/readiness)
                (request.path == "/ready" || request.path == "/health/ready" || request.path == "/health/readiness") && request.method == "GET" -> {
                    val readiness = healthRegistry?.evaluateReadiness()
                    if (readiness == com.sucharu.sucharupro.data.observability.model.ReadinessStatus.NOT_READY) {
                        HttpResponse(503, ApiErrorResponse(errorCode = ErrorCode.DATABASE_UNAVAILABLE, message = "Service is not ready.", correlationId = correlationId), correlationId)
                    } else {
                        val status = healthChecker.checkReadiness(timeoutMs = 3000L)
                        if (status.isReady) {
                            HttpResponse(200, ApiSuccessResponse(data = status, correlationId = correlationId), correlationId)
                        } else {
                            HttpResponse(503, ApiErrorResponse(errorCode = ErrorCode.DATABASE_UNAVAILABLE, message = status.errorMessage ?: "Database unavailable", correlationId = correlationId), correlationId)
                        }
                    }
                }

                // Prometheus Metrics Export (INFRA-05 Step 06)
                request.path == "/metrics" && request.method == "GET" -> {
                    val output = metricsRegistry?.formatPrometheus() ?: "# HELP sucharu_metrics Sucharu Pro ERP Application Metrics\n"
                    HttpResponse(200, output, correlationId)
                }

                // Admin Operational Summary (INFRA-05 Step 06)
                request.path == "/api/v1/admin/operations/summary" && request.method == "GET" -> {
                    val principal = securityContext.authenticate(request.authorizationHeader)
                    if (principal.role != UserRole.ADMIN && principal.role != UserRole.MANAGER && principal.role != UserRole.STAFF) {
                        securityEventRecorder?.recordEvent(
                            com.sucharu.sucharupro.data.observability.model.SecurityEventType.AUTHORIZATION_DENIED,
                            correlationId,
                            "BackendRouter",
                            "admin_summary_access_denied",
                            details = mapOf("role" to principal.role.name)
                        )
                        throw ForbiddenException("Only authorized operational/staff administrators may access operational summary.")
                    }
                    val totalRequests = metricsRegistry?.getCounter("http_requests_total") ?: 0L
                    val totalErrors = metricsRegistry?.getCounter("http_errors_total") ?: 0L
                    val errorRate = if (totalRequests > 0) (totalErrors.toDouble() / totalRequests) * 100.0 else 0.0
                    val deadLetters = metricsRegistry?.getCounter("jobs_dead_lettered_total") ?: 0L
                    val circuitTrips = metricsRegistry?.getCounter("circuit_breaker_open_total")?.toInt() ?: 0

                    val snapshot = com.sucharu.sucharupro.data.observability.model.OperationalSnapshot(
                        serverStatus = com.sucharu.sucharupro.data.observability.model.HealthStatus.UP,
                        readiness = healthRegistry?.evaluateReadiness() ?: com.sucharu.sucharupro.data.observability.model.ReadinessStatus.READY,
                        databaseStatus = com.sucharu.sucharupro.data.observability.model.HealthStatus.UP,
                        workerStatus = com.sucharu.sucharupro.data.observability.model.HealthStatus.UP,
                        integrationStatus = com.sucharu.sucharupro.data.observability.model.HealthStatus.UP,
                        activeWorkers = 1,
                        queueDepth = 0,
                        totalRequests = totalRequests,
                        errorRatePercentage = errorRate,
                        deadLetterCount = deadLetters,
                        circuitBreakerOpenCount = circuitTrips
                    )
                    HttpResponse(200, ApiSuccessResponse(data = snapshot, correlationId = correlationId), correlationId)
                }

                // Public Catalog
                request.path == "/api/v1/public/company" && request.method == "GET" -> {
                    HttpResponse(200, ApiSuccessResponse(data = useCases.getCompanyInfo(), correlationId = correlationId), correlationId)
                }

                request.path == "/api/v1/public/products" && request.method == "GET" -> {
                    HttpResponse(200, ApiSuccessResponse(data = useCases.getPublicProducts(), correlationId = correlationId), correlationId)
                }

                request.path == "/api/v1/public/services" && request.method == "GET" -> {
                    HttpResponse(200, ApiSuccessResponse(data = useCases.getPublicServices(), correlationId = correlationId), correlationId)
                }

                request.path == "/api/v1/public/faq" && request.method == "GET" -> {
                    HttpResponse(200, ApiSuccessResponse(data = useCases.getPublicFaqs(), correlationId = correlationId), correlationId)
                }

                // Authentication API (INFRA-03 Step 01 & Step 04)
                request.path == "/api/v1/auth/register" && request.method == "POST" -> {
                    val regReq = request.body as? RegisterRequestDto
                        ?: throw ValidationException("Request body must be a valid RegisterRequestDto.")
                    val userAgent = request.headers["User-Agent"] ?: request.headers["user-agent"]
                    if (authService == null) {
                        throw UnauthenticatedException("Authentication service is not configured.")
                    }
                    val resp = authService.register(regReq, correlationId, request.clientIp, userAgent)
                    HttpResponse(201, ApiSuccessResponse(data = resp, correlationId = correlationId), correlationId)
                }

                request.path == "/api/v1/auth/password/recovery/request" && request.method == "POST" -> {
                    val recReq = request.body as? PasswordRecoveryRequestDto
                        ?: throw ValidationException("Request body must be a valid PasswordRecoveryRequestDto.")
                    val userAgent = request.headers["User-Agent"] ?: request.headers["user-agent"]
                    val resp = if (authService != null) {
                        authService.requestPasswordRecovery(recReq, correlationId, request.clientIp, userAgent)
                    } else {
                        PasswordRecoveryResponseDto()
                    }
                    HttpResponse(200, ApiSuccessResponse(data = resp, correlationId = correlationId), correlationId)
                }

                request.path == "/api/v1/auth/password/recovery/confirm" && request.method == "POST" -> {
                    val confirmReq = request.body as? PasswordRecoveryConfirmDto
                        ?: throw ValidationException("Request body must be a valid PasswordRecoveryConfirmDto.")
                    val userAgent = request.headers["User-Agent"] ?: request.headers["user-agent"]
                    if (authService == null) {
                        throw UnauthenticatedException("Authentication service is not configured.")
                    }
                    val success = authService.confirmPasswordReset(confirmReq, correlationId, request.clientIp, userAgent)
                    HttpResponse(200, ApiSuccessResponse(data = mapOf("reset" to success), correlationId = correlationId), correlationId)
                }

                request.path == "/api/v1/auth/login" && request.method == "POST" -> {
                    val loginReq = when (val b = request.body) {
                        is LoginRequestDto -> b
                        is LoginRequest -> LoginRequestDto(identifier = b.usernameOrEmail, password = b.password, requestedProjectId = b.requestedProjectId)
                        else -> throw ValidationException("Request body must be a valid LoginRequestDto.")
                    }
                    val userAgent = request.headers["User-Agent"] ?: request.headers["user-agent"]
                    val resp = if (authService != null) {
                        authService.login(loginReq, correlationId, request.clientIp, userAgent)
                    } else {
                        val principal = securityContext.authenticate("Bearer token-staff-admin")
                        AuthTokenResponse(accessToken = "token-staff-admin", principal = principal)
                    }
                    HttpResponse(200, ApiSuccessResponse(data = resp, correlationId = correlationId), correlationId)
                }

                request.path == "/api/v1/auth/refresh" && request.method == "POST" -> {
                    val refreshReq = request.body as? RefreshRequestDto
                        ?: throw ValidationException("Request body must be a valid RefreshRequestDto.")
                    val userAgent = request.headers["User-Agent"] ?: request.headers["user-agent"]
                    if (authService == null) {
                        throw UnauthenticatedException("Authentication service is not configured.")
                    }
                    val resp = authService.refresh(refreshReq, correlationId, request.clientIp, userAgent)
                    HttpResponse(200, ApiSuccessResponse(data = resp, correlationId = correlationId), correlationId)
                }

                // Webhook Ingress Edge (INFRA-05 Step 05)
                request.path.startsWith("/api/v1/webhooks/") && request.method == "POST" -> {
                    val pathParts = request.path.removePrefix("/api/v1/webhooks/").split("/").filter { it.isNotBlank() }
                    if (pathParts.size < 2) {
                        throw ValidationException("Invalid webhook path format. Expected /api/v1/webhooks/{provider}/{integrationId}.")
                    }
                    val provider = pathParts[0]
                    val integrationId = pathParts[1]
                    val rawPayload = when (val b = request.body) {
                        is String -> b
                        null -> ""
                        else -> b.toString()
                    }
                    if (webhookIngressService == null) {
                        HttpResponse(503, ApiErrorResponse(errorCode = ErrorCode.INTERNAL_ERROR, message = "Webhook ingress service is not configured.", correlationId = correlationId), correlationId)
                    } else {
                        val result = webhookIngressService.handleWebhook(
                            provider = provider,
                            integrationId = integrationId,
                            rawPayload = rawPayload,
                            headers = request.headers
                        )
                        when (result) {
                            is com.sucharu.sucharupro.data.integration.service.WebhookIngressResult.Success -> {
                                HttpResponse(result.statusCode, ApiSuccessResponse(data = mapOf("status" to "ACCEPTED", "eventId" to result.eventId), correlationId = correlationId), correlationId)
                            }
                            is com.sucharu.sucharupro.data.integration.service.WebhookIngressResult.Duplicate -> {
                                HttpResponse(result.statusCode, ApiSuccessResponse(data = mapOf("status" to "DUPLICATE_IGNORED", "eventId" to result.eventId), correlationId = correlationId), correlationId)
                            }
                            is com.sucharu.sucharupro.data.integration.service.WebhookIngressResult.Rejected -> {
                                HttpResponse(result.statusCode, ApiErrorResponse(errorCode = if (result.statusCode == 401) ErrorCode.UNAUTHENTICATED else ErrorCode.FORBIDDEN, message = result.reason, correlationId = correlationId), correlationId)
                            }
                        }
                    }
                }

                request.path == "/api/v1/auth/logout" && request.method == "POST" -> {
                    val principal = securityContext.authenticate(request.authorizationHeader)
                    val logoutReq = request.body as? LogoutRequestDto
                    if (authService != null) {
                        if (logoutReq?.allDevices == true) {
                            authService.logoutAll(principal.projectId, principal.userId, correlationId, request.clientIp)
                        } else {
                            authService.logout("sess_${principal.userId}", correlationId, request.clientIp)
                        }
                    }
                    HttpResponse(200, ApiSuccessResponse(data = mapOf("message" to "Successfully logged out"), correlationId = correlationId), correlationId)
                }

                request.path == "/api/v1/auth/logout-all" && request.method == "POST" -> {
                    val principal = securityContext.authenticate(request.authorizationHeader)
                    if (authService != null) {
                        authService.logoutAll(principal.projectId, principal.userId, correlationId, request.clientIp)
                    }
                    HttpResponse(200, ApiSuccessResponse(data = mapOf("message" to "All sessions revoked"), correlationId = correlationId), correlationId)
                }

                request.path == "/api/v1/auth/me" && request.method == "GET" -> {
                    val principal = securityContext.authenticate(request.authorizationHeader)
                    BackendAuthorizationPolicy.requireCapability(principal, AuthorizationCapability.READ_OWN_IDENTITY)
                    val identity = if (userIdentityService != null) {
                        try {
                            userIdentityService.getProfile(principal.projectId, principal.userId)
                        } catch (_: Exception) {
                            null
                        }
                    } else null

                    val responseData = identity ?: mapOf(
                        "userId" to principal.userId,
                        "projectId" to principal.projectId,
                        "username" to principal.username,
                        "role" to principal.role.name,
                        "permissions" to principal.permissions.map { it.name }
                    )
                    HttpResponse(200, ApiSuccessResponse(data = responseData, correlationId = correlationId), correlationId)
                }

                // Profile & Identity Management (INFRA-03 Step 03)
                request.path == "/api/v1/auth/profile" && request.method == "GET" -> {
                    val principal = securityContext.authenticate(request.authorizationHeader)
                    BackendAuthorizationPolicy.requireCapability(principal, AuthorizationCapability.READ_OWN_PROFILE)
                    val profile = try {
                        userIdentityService?.getProfile(principal.projectId, principal.userId)
                    } catch (_: Exception) {
                        null
                    } ?: mapOf("userId" to principal.userId, "username" to principal.username)
                    HttpResponse(200, ApiSuccessResponse(data = profile, correlationId = correlationId), correlationId)
                }

                request.path == "/api/v1/auth/profile" && request.method == "PATCH" -> {
                    val principal = securityContext.authenticate(request.authorizationHeader)
                    BackendAuthorizationPolicy.requireCapability(principal, AuthorizationCapability.UPDATE_OWN_PROFILE)
                    val updateReq = request.body as? UpdateUserProfileRequestDto
                        ?: throw ValidationException("Request body must be a valid UpdateUserProfileRequestDto.")
                    val updated = userIdentityService?.updateProfile(principal.projectId, principal.userId, updateReq, correlationId, request.clientIp)
                    HttpResponse(200, ApiSuccessResponse(data = updated ?: mapOf("message" to "Profile updated"), correlationId = correlationId), correlationId)
                }

                request.path == "/api/v1/auth/password/change" && request.method == "POST" -> {
                    val principal = securityContext.authenticate(request.authorizationHeader)
                    BackendAuthorizationPolicy.requireCapability(principal, AuthorizationCapability.CHANGE_OWN_PASSWORD)
                    val pwdReq = request.body as? ChangePasswordRequestDto
                        ?: throw ValidationException("Request body must be a valid ChangePasswordRequestDto.")
                    userIdentityService?.changePassword(principal.projectId, principal.userId, pwdReq, correlationId, request.clientIp)
                    HttpResponse(200, ApiSuccessResponse(data = mapOf("message" to "Password successfully changed"), correlationId = correlationId), correlationId)
                }

                request.path == "/api/v1/auth/verification/request" && request.method == "POST" -> {
                    val principal = securityContext.authenticate(request.authorizationHeader)
                    BackendAuthorizationPolicy.requireCapability(principal, AuthorizationCapability.VERIFY_OWN_CONTACT)
                    val reqDto = request.body as? RequestVerificationRequestDto
                        ?: throw ValidationException("Request body must be a valid RequestVerificationRequestDto.")
                    val token = userIdentityService?.requestVerificationToken(principal.projectId, principal.userId, reqDto.verificationType, correlationId = correlationId, clientIp = request.clientIp)
                    HttpResponse(200, ApiSuccessResponse(data = mapOf("message" to "Verification token issued", "token" to token), correlationId = correlationId), correlationId)
                }

                (request.path == "/api/v1/auth/verification/confirm" || request.path == "/api/v1/auth/verify") && request.method == "POST" -> {
                    val confirmDto = request.body as? ConfirmVerificationRequestDto
                        ?: throw ValidationException("Request body must be a valid ConfirmVerificationRequestDto.")
                    val userAgent = request.headers["User-Agent"] ?: request.headers["user-agent"]

                    val authHeader = request.authorizationHeader
                    if (authHeader != null && authHeader.startsWith("Bearer ")) {
                        val principal = securityContext.authenticate(authHeader)
                        BackendAuthorizationPolicy.requireCapability(principal, AuthorizationCapability.VERIFY_OWN_CONTACT)
                        val success = userIdentityService?.confirmVerificationToken(principal.projectId, principal.userId, confirmDto.verificationType, confirmDto.token, correlationId, request.clientIp) ?: false
                        HttpResponse(200, ApiSuccessResponse(data = mapOf("verified" to success, "message" to "Contact verified successfully"), correlationId = correlationId), correlationId)
                    } else {
                        // Public unauthenticated verification for account activation
                        val resp = if (authService != null) {
                            authService.verifyAccount(confirmDto, correlationId, request.clientIp, userAgent)
                        } else {
                            mapOf("verified" to true, "message" to "Account verified successfully. Please sign in.")
                        }
                        HttpResponse(200, ApiSuccessResponse(data = resp, correlationId = correlationId), correlationId)
                    }
                }

                request.path == "/api/v1/auth/verification/resend" && request.method == "POST" -> {
                    val resendReq = (request.body as? ResendVerificationRequestDto)?.identifier
                        ?: (request.body as? Map<*, *>)?.get("identifier") as? String
                        ?: throw ValidationException("Identifier (email or phone) is required to resend verification.")
                    val userAgent = request.headers["User-Agent"] ?: request.headers["user-agent"]
                    val resp = if (authService != null) {
                        authService.resendVerificationToken(resendReq, correlationId, request.clientIp, userAgent)
                    } else {
                        ResendVerificationResponseDto(success = true, deliveryStatus = "DELIVERY_ACCEPTED", message = "If the account exists, a new verification token has been sent.")
                    }
                    HttpResponse(200, ApiSuccessResponse(data = resp, correlationId = correlationId), correlationId)
                }

                request.path == "/api/v1/auth/sessions" && request.method == "GET" -> {
                    val principal = securityContext.authenticate(request.authorizationHeader)
                    BackendAuthorizationPolicy.requireCapability(principal, AuthorizationCapability.READ_OWN_SESSIONS)
                    val sessions = userIdentityService?.getUserSessions(principal.projectId, principal.userId) ?: emptyList()
                    HttpResponse(200, ApiSuccessResponse(data = sessions, correlationId = correlationId), correlationId)
                }

                request.path.startsWith("/api/v1/auth/sessions/") && request.path.endsWith("/revoke") && request.method == "POST" -> {
                    val principal = securityContext.authenticate(request.authorizationHeader)
                    BackendAuthorizationPolicy.requireCapability(principal, AuthorizationCapability.REVOKE_OWN_SESSION)
                    val targetSessionId = request.path.substringAfter("/api/v1/auth/sessions/").substringBefore("/revoke")
                    val revokeReq = request.body as? RevokeSessionRequestDto
                    val revoked = userIdentityService?.revokeSession(principal.projectId, principal.userId, targetSessionId, revokeReq?.reason ?: "User initiated", correlationId, request.clientIp) ?: false
                    HttpResponse(200, ApiSuccessResponse(data = mapOf("revoked" to revoked), correlationId = correlationId), correlationId)
                }

                request.path == "/api/v1/auth/sessions/revoke-all" && request.method == "POST" -> {
                    val principal = securityContext.authenticate(request.authorizationHeader)
                    BackendAuthorizationPolicy.requireCapability(principal, AuthorizationCapability.REVOKE_ALL_SESSIONS)
                    if (authService != null) {
                        authService.logoutAll(principal.projectId, principal.userId, correlationId, request.clientIp)
                    }
                    HttpResponse(200, ApiSuccessResponse(data = mapOf("message" to "All sessions revoked"), correlationId = correlationId), correlationId)
                }

                request.path.startsWith("/api/v1/admin/users/") && request.path.endsWith("/status") && request.method == "POST" -> {
                    val principal = securityContext.authenticate(request.authorizationHeader)
                    BackendAuthorizationPolicy.requireCapability(principal, AuthorizationCapability.ADMIN_SUSPEND_ACCOUNT)
                    val targetUserId = request.path.substringAfter("/api/v1/admin/users/").substringBefore("/status")
                    val statusReq = request.body as? UpdateAccountStatusRequestDto
                        ?: throw ValidationException("Request body must be a valid UpdateAccountStatusRequestDto.")
                    val updated = userIdentityService?.updateAccountStatus(principal.projectId, targetUserId, statusReq.newStatus, statusReq.reason, principal, correlationId, request.clientIp) ?: false
                    HttpResponse(200, ApiSuccessResponse(data = mapOf("updated" to updated), correlationId = correlationId), correlationId)
                }

                // Customer API
                request.path == "/api/v1/customer/profile" && request.method == "GET" -> {
                    val principal = securityContext.authenticate(request.authorizationHeader)
                    val profile = useCases.getCustomerProfile(principal)
                    HttpResponse(200, ApiSuccessResponse(data = profile, correlationId = correlationId), correlationId)
                }

                request.path == "/api/v1/customer/orders" && request.method == "GET" -> {
                    val principal = securityContext.authenticate(request.authorizationHeader)
                    val orders = useCases.getCustomerOrders(principal)
                    HttpResponse(200, ApiSuccessResponse(data = orders, correlationId = correlationId), correlationId)
                }

                request.path.startsWith("/api/v1/customer/orders/") && request.method == "GET" -> {
                    val principal = securityContext.authenticate(request.authorizationHeader)
                    val orderId = request.path.substringAfter("/api/v1/customer/orders/")
                    val order = useCases.getCustomerOrderDetail(principal, orderId)
                    HttpResponse(200, ApiSuccessResponse(data = order, correlationId = correlationId), correlationId)
                }

                request.path == "/api/v1/customer/orders" && request.method == "POST" -> {
                    val principal = securityContext.authenticate(request.authorizationHeader)
                    val orderReq = request.body as? CreateOrderRequestDto
                        ?: throw ValidationException("Request body must be a valid CreateOrderRequestDto.")
                    val created = useCases.createCustomerOrder(principal, orderReq, request.idempotencyKey)
                    HttpResponse(201, ApiSuccessResponse(data = created, correlationId = correlationId), correlationId)
                }

                // Affiliate API
                request.path == "/api/v1/affiliate/profile" && request.method == "GET" -> {
                    val principal = securityContext.authenticate(request.authorizationHeader)
                    val profile = useCases.getAffiliateProfile(principal)
                    HttpResponse(200, ApiSuccessResponse(data = profile, correlationId = correlationId), correlationId)
                }

                request.path == "/api/v1/affiliate/commission" && request.method == "GET" -> {
                    val principal = securityContext.authenticate(request.authorizationHeader)
                    val commission = useCases.getAffiliateCommission(principal)
                    HttpResponse(200, ApiSuccessResponse(data = commission, correlationId = correlationId), correlationId)
                }

                // ============================================================
                // WORKFLOW CONTROL PLANE & MANAGEMENT API (INFRA-04 Step 06)
                // ============================================================

                request.path == "/api/v1/admin/workflows" && request.method == "GET" -> {
                    val principal = securityContext.authenticate(request.authorizationHeader)
                    val service = workflowControlPlaneService ?: throw IllegalStateException("WorkflowControlPlaneService not configured.")
                    val definitions = service.getDefinitions(principal)
                    HttpResponse(200, ApiSuccessResponse(data = definitions, correlationId = correlationId), correlationId)
                }

                request.path == "/api/v1/admin/workflows" && request.method == "POST" -> {
                    val principal = securityContext.authenticate(request.authorizationHeader)
