                request.path.startsWith("/api/v1/vendor-work-orders/") && request.path.endsWith("/cancel") && request.method == "POST" -> {
                    val principal = securityContext.authenticate(request.authorizationHeader)
                    val workOrderId = request.path.substringAfter("/api/v1/vendor-work-orders/").substringBefore("/cancel")
                    val updated = useCases.changeVendorWorkOrderStatus(principal, workOrderId, com.sucharu.sucharupro.domain.model.vendor.VendorWorkOrderStatus.CANCELLED, "Cancelled work order")
                    HttpResponse(200, ApiSuccessResponse(data = updated, correlationId = correlationId), correlationId)
                }

                request.path.startsWith("/api/v1/vendor-work-orders/") && (request.method == "PUT" || request.method == "PATCH") -> {
                    val principal = securityContext.authenticate(request.authorizationHeader)
                    val workOrderId = request.path.substringAfter("/api/v1/vendor-work-orders/")
                    val reqDto = when (val b = request.body) {
                        is UpdateVendorWorkOrderRequestDto -> b
                        is Map<*, *> -> UpdateVendorWorkOrderRequestDto(
                            title = b["title"]?.toString(),
                            description = b["description"]?.toString(),
                            quantity = (b["quantity"] as? Number)?.toDouble(),
                            scheduledStartAt = (b["scheduledStartAt"] as? Number)?.toLong(),
                            scheduledDueAt = (b["scheduledDueAt"] as? Number)?.toLong(),
                            priority = b["priority"]?.toString(),
                            notes = b["notes"]?.toString()
                        )
                        is String -> {
                            val map = com.sucharu.sucharupro.data.event.serialization.EventSerializationHelper.parseJsonObject(b)
                            UpdateVendorWorkOrderRequestDto(
                                title = map["title"],
                                description = map["description"],
                                quantity = map["quantity"]?.toDoubleOrNull(),
                                scheduledStartAt = map["scheduledStartAt"]?.toLongOrNull(),
                                scheduledDueAt = map["scheduledDueAt"]?.toLongOrNull(),
                                priority = map["priority"],
                                notes = map["notes"]
                            )
                        }
                        else -> throw ValidationException("Request body must be a valid UpdateVendorWorkOrderRequestDto.")
                    }
                    val updated = useCases.updateVendorWorkOrder(principal, workOrderId, reqDto)
                    HttpResponse(200, ApiSuccessResponse(data = updated, correlationId = correlationId), correlationId)
                }

                request.path.startsWith("/api/v1/vendor-work-orders/") && request.method == "GET" -> {
                    val principal = securityContext.authenticate(request.authorizationHeader)
                    val workOrderId = request.path.substringAfter("/api/v1/vendor-work-orders/")
                    val order = useCases.getVendorWorkOrderById(principal, workOrderId)
                    HttpResponse(200, ApiSuccessResponse(data = order, correlationId = correlationId), correlationId)
                }

                else -> {
                    handleVendorPurchaseOrderRoutes(request, correlationId)
                        ?: handleVendorDeliveryReceiptRoutes(request, correlationId)
                        ?: handleVendorInvoiceRoutes(request, correlationId)
                        ?: handleVendorQualityRoutes(request, correlationId)
                        ?: handleVendorPerformanceRoutes(request, correlationId)
                        ?: handleVendorComplianceRoutes(request, correlationId)
                        ?: handleVendorCorrectiveActionRoutes(request, correlationId)
                        ?: handleVendorPortalRoutes(request, correlationId)
                        ?: HttpResponse(404, ApiErrorResponse(errorCode = ErrorCode.NOT_FOUND, message = "Route '${request.path}' not found.", correlationId = correlationId), correlationId)
                }

            }
        } catch (e: UnauthenticatedException) {
            securityEventRecorder?.recordEvent(
                com.sucharu.sucharupro.data.observability.model.SecurityEventType.AUTHENTICATION_FAILED,
                correlationId,
                "BackendRouter",
                "unauthenticated"
            )
            HttpResponse(401, ApiErrorResponse(errorCode = ErrorCode.UNAUTHENTICATED, message = e.message ?: "Authentication required", correlationId = correlationId), correlationId)
        } catch (e: ForbiddenException) {
            securityEventRecorder?.recordEvent(
                com.sucharu.sucharupro.data.observability.model.SecurityEventType.AUTHORIZATION_DENIED,
                correlationId,
                "BackendRouter",
                "forbidden"
            )
            HttpResponse(403, ApiErrorResponse(errorCode = ErrorCode.FORBIDDEN, message = e.message ?: "Forbidden", correlationId = correlationId), correlationId)
        } catch (e: NotFoundException) {
            HttpResponse(404, ApiErrorResponse(errorCode = ErrorCode.NOT_FOUND, message = e.message ?: "Not found", correlationId = correlationId), correlationId)
        } catch (e: ConflictException) {
            HttpResponse(409, ApiErrorResponse(errorCode = e.errorCode, message = e.message ?: "Conflict", correlationId = correlationId), correlationId)
        } catch (e: ValidationException) {
            HttpResponse(400, ApiErrorResponse(errorCode = ErrorCode.VALIDATION_ERROR, message = e.message ?: "Validation error", details = e.errorResponse.details, correlationId = correlationId), correlationId)
        } catch (e: DatabaseUnavailableException) {
            HttpResponse(503, ApiErrorResponse(errorCode = ErrorCode.DATABASE_UNAVAILABLE, message = e.message ?: "Database unavailable", correlationId = correlationId), correlationId)
        } catch (e: ApiException) {
            val status = when (e.errorResponse.errorCode) {
                ErrorCode.RATE_LIMITED -> 429
                ErrorCode.UNAUTHENTICATED -> {
                    securityEventRecorder?.recordEvent(
                        com.sucharu.sucharupro.data.observability.model.SecurityEventType.AUTHENTICATION_FAILED,
                        correlationId,
                        "BackendRouter",
                        "unauthenticated"
                    )
                    401
                }
                ErrorCode.FORBIDDEN -> {
                    securityEventRecorder?.recordEvent(
                        com.sucharu.sucharupro.data.observability.model.SecurityEventType.AUTHORIZATION_DENIED,
                        correlationId,
                        "BackendRouter",
                        "forbidden"
                    )
                    403
                }
                ErrorCode.NOT_FOUND -> 404
                ErrorCode.CONFLICT, ErrorCode.OPTIMISTIC_CONCURRENCY_CONFLICT, ErrorCode.IDEMPOTENCY_CONFLICT -> 409
                ErrorCode.VALIDATION_ERROR -> 400
                ErrorCode.DATABASE_UNAVAILABLE -> 503
                else -> 500
            }
            HttpResponse(status, e.errorResponse.copy(correlationId = correlationId), correlationId)
        } catch (e: Throwable) {
            // Sanitized internal error: never leak raw stack trace or database errors
            HttpResponse(500, ApiErrorResponse(errorCode = ErrorCode.INTERNAL_ERROR, message = "An internal server error occurred.", correlationId = correlationId), correlationId)
        }

        val durationMs = System.currentTimeMillis() - startTime
        try {
            metricsRegistry?.recordHttpRequest(request.method, request.path, response.statusCode, durationMs)
            if (durationMs > slowRequestThresholdMs) {
                metricsRegistry?.recordSlowRequest(request.path, request.method, durationMs)
            }
        } catch (_: Exception) {
            // Fail-safe: Metrics recording failure must never fail business request
        }

        return response
    }

    // =========================================================================
    // 14. VENDOR PURCHASE ORDER SUB-ROUTER (Module 12 Step 05)
    // =========================================================================
    private suspend fun handleVendorPurchaseOrderRoutes(request: HttpRequest, correlationId: String): HttpResponse? = when {
        request.path == "/api/v1/vendor-purchase-orders" && request.method == "POST" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            BackendAuthorizationPolicy.requireRole(principal, UserRole.ADMIN, UserRole.MANAGER, UserRole.STAFF)
            val reqDto = when (val b = request.body) {
                is CreateVendorPurchaseOrderRequestDto -> b
                is Map<*, *> -> CreateVendorPurchaseOrderRequestDto(
                    vendorId = b["vendorId"]?.toString() ?: "",
                    requestedBy = b["requestedBy"]?.toString(),
                    items = (b["items"] as? List<*>)?.mapNotNull { itemMap ->
                        if (itemMap is Map<*, *>) {
                            VendorPurchaseOrderItemDto(
                                itemId = itemMap["itemId"]?.toString(),
                                vendorServiceRateId = itemMap["vendorServiceRateId"]?.toString(),
                                capabilityType = itemMap["capabilityType"]?.toString(),
                                itemDescription = itemMap["itemDescription"]?.toString() ?: "",
                                itemCode = itemMap["itemCode"]?.toString(),
                                quantity = (itemMap["quantity"] as? Number)?.toDouble() ?: 1.0,
                                unitOfMeasure = itemMap["unitOfMeasure"]?.toString() ?: "PIECE",
                                unitRate = (itemMap["unitRate"] as? Number)?.toDouble() ?: 0.0,
                                pricingMethod = itemMap["pricingMethod"]?.toString() ?: "PER_UNIT",
                                currency = itemMap["currency"]?.toString() ?: "BDT",
                                discount = (itemMap["discount"] as? Number)?.toDouble() ?: 0.0,
                                taxAmount = (itemMap["taxAmount"] as? Number)?.toDouble() ?: 0.0,
                                expectedDeliveryDate = (itemMap["expectedDeliveryDate"] as? Number)?.toLong(),
                                notes = itemMap["notes"]?.toString(),
                                sourceWorkOrderId = itemMap["sourceWorkOrderId"]?.toString()
                            )
                        } else null
                    } ?: emptyList(),
                    expectedDeliveryDate = (b["expectedDeliveryDate"] as? Number)?.toLong(),
                    deliveryLocation = b["deliveryLocation"]?.toString(),
                    currency = b["currency"]?.toString() ?: "BDT",
                    taxAmount = (b["taxAmount"] as? Number)?.toDouble() ?: 0.0,
                    discountAmount = (b["discountAmount"] as? Number)?.toDouble() ?: 0.0,
                    notes = b["notes"]?.toString(),
                    sourceReferenceType = b["sourceReferenceType"]?.toString(),
                    sourceReferenceId = b["sourceReferenceId"]?.toString()
                )
                is String -> {
                    val map = com.sucharu.sucharupro.data.event.serialization.EventSerializationHelper.parseJsonObject(b)
                    CreateVendorPurchaseOrderRequestDto(
                        vendorId = map["vendorId"] ?: "",
                        requestedBy = map["requestedBy"],
                        items = emptyList(),
                        expectedDeliveryDate = map["expectedDeliveryDate"]?.toLongOrNull(),
                        deliveryLocation = map["deliveryLocation"],
                        currency = map["currency"] ?: "BDT",
                        taxAmount = map["taxAmount"]?.toDoubleOrNull() ?: 0.0,
                        discountAmount = map["discountAmount"]?.toDoubleOrNull() ?: 0.0,
                        notes = map["notes"],
                        sourceReferenceType = map["sourceReferenceType"],
                        sourceReferenceId = map["sourceReferenceId"]
                    )
                }
                else -> throw ValidationException("Request body must be a valid CreateVendorPurchaseOrderRequestDto.")
            }
            val created = useCases.createVendorPurchaseOrder(principal, reqDto)
            HttpResponse(201, ApiSuccessResponse(data = created, correlationId = correlationId), correlationId)
        }

        request.path.startsWith("/api/v1/vendor-purchase-orders") && (request.path == "/api/v1/vendor-purchase-orders" || request.path.startsWith("/api/v1/vendor-purchase-orders?")) && request.method == "GET" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            BackendAuthorizationPolicy.requireRole(principal, UserRole.ADMIN, UserRole.MANAGER, UserRole.STAFF)
            val queryParams = if (request.path.contains("?")) {
                request.path.substringAfter("?").split("&").mapNotNull {
                    val parts = it.split("=")
                    if (parts.size == 2) parts[0] to parts[1] else null
                }.toMap()
            } else emptyMap()
            val vendorId = queryParams["vendorId"]
            val status = queryParams["status"]
            val sourceReferenceType = queryParams["sourceReferenceType"]
            val sourceReferenceId = queryParams["sourceReferenceId"]
            val list = useCases.listVendorPurchaseOrders(principal, vendorId, status, sourceReferenceType, sourceReferenceId)
            HttpResponse(200, ApiSuccessResponse(data = list, correlationId = correlationId), correlationId)
        }

        request.path.startsWith("/api/v1/vendors/") && request.path.endsWith("/purchase-orders") && request.method == "GET" -> {
