                is ReviseVendorPurchaseOrderRequestDto -> b
                is Map<*, *> -> ReviseVendorPurchaseOrderRequestDto(
                    updatedItems = (b["updatedItems"] as? List<*>)?.mapNotNull { itemMap ->
                        if (itemMap is Map<*, *>) {
                            VendorPurchaseOrderItemDto(
                                itemId = itemMap["itemId"]?.toString(),
                                vendorServiceRateId = itemMap["vendorServiceRateId"]?.toString(),
