    // =========================================================================
    // 15. VENDOR DELIVERY RECEIPT SUB-ROUTER (Step 06)
    // =========================================================================
    private suspend fun handleVendorDeliveryReceiptRoutes(request: HttpRequest, correlationId: String): HttpResponse? = when {
        request.path == "/api/v1/vendor-delivery-receipts" && request.method == "POST" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            BackendAuthorizationPolicy.requireRole(principal, UserRole.ADMIN, UserRole.MANAGER, UserRole.STAFF)
            val reqDto = when (val b = request.body) {
                is CreateVendorDeliveryReceiptRequestDto -> b
                is Map<*, *> -> CreateVendorDeliveryReceiptRequestDto(
                    purchaseOrderId = b["purchaseOrderId"]?.toString() ?: "",
                    vendorDeliveryReference = b["vendorDeliveryReference"]?.toString(),
                    warehouseId = b["warehouseId"]?.toString(),
                    remarks = b["remarks"]?.toString(),
                    items = (b["items"] as? List<*>)?.mapNotNull { itemRaw ->
                        val itemMap = itemRaw as? Map<*, *>
                        if (itemMap != null) {
                            VendorDeliveryReceiptItemDto(
                                receiptItemId = itemMap["receiptItemId"]?.toString() ?: "",
                                purchaseOrderItemId = itemMap["purchaseOrderItemId"]?.toString() ?: "",
                                itemDescription = itemMap["itemDescription"]?.toString() ?: "",
                                itemCode = itemMap["itemCode"]?.toString(),
                                receivedQuantity = (itemMap["receivedQuantity"] as? Number)?.toDouble() ?: 0.0,
                                acceptedQuantity = (itemMap["acceptedQuantity"] as? Number)?.toDouble() ?: 0.0,
                                rejectedQuantity = (itemMap["rejectedQuantity"] as? Number)?.toDouble() ?: 0.0,
                                damagedQuantity = (itemMap["damagedQuantity"] as? Number)?.toDouble() ?: 0.0,
                                shortQuantity = (itemMap["shortQuantity"] as? Number)?.toDouble() ?: 0.0,
                                excessQuantity = (itemMap["excessQuantity"] as? Number)?.toDouble() ?: 0.0,
                                remarks = itemMap["remarks"]?.toString()
                            )
                        } else null
                    } ?: emptyList()
                )
                else -> throw ValidationException("Request body must be a valid CreateVendorDeliveryReceiptRequestDto.")
            }
            val created = useCases.createVendorDeliveryReceipt(principal, reqDto)
            HttpResponse(201, ApiSuccessResponse(data = created, correlationId = correlationId), correlationId)
        }

        request.path.startsWith("/api/v1/vendor-delivery-receipts") && (request.path == "/api/v1/vendor-delivery-receipts" || request.path.startsWith("/api/v1/vendor-delivery-receipts?")) && request.method == "GET" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            BackendAuthorizationPolicy.requireRole(principal, UserRole.ADMIN, UserRole.MANAGER, UserRole.STAFF)
            val queryParams = if (request.path.contains("?")) {
                request.path.substringAfter("?").split("&").mapNotNull {
                    val parts = it.split("=")
                    if (parts.size == 2) parts[0] to parts[1] else null
                }.toMap()
            } else emptyMap()
            val vendorId = queryParams["vendorId"]
            val purchaseOrderId = queryParams["purchaseOrderId"]
            val status = queryParams["status"]
            val list = useCases.listVendorDeliveryReceipts(principal, vendorId, purchaseOrderId, status)
            HttpResponse(200, ApiSuccessResponse(data = list, correlationId = correlationId), correlationId)
        }

        request.path.startsWith("/api/v1/vendor-delivery-receipts/number/") && request.method == "GET" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            BackendAuthorizationPolicy.requireRole(principal, UserRole.ADMIN, UserRole.MANAGER, UserRole.STAFF)
            val receiptNumber = request.path.substringAfter("/api/v1/vendor-delivery-receipts/number/")
            val receipt = useCases.getVendorDeliveryReceiptByNumber(principal, receiptNumber)
            HttpResponse(200, ApiSuccessResponse(data = receipt, correlationId = correlationId), correlationId)
        }

        request.path.startsWith("/api/v1/vendors/") && request.path.endsWith("/delivery-receipts") && request.method == "GET" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            BackendAuthorizationPolicy.requireRole(principal, UserRole.ADMIN, UserRole.MANAGER, UserRole.STAFF)
            val vendorId = request.path.substringAfter("/api/v1/vendors/").substringBefore("/delivery-receipts")
            val list = useCases.listVendorDeliveryReceipts(principal, vendorId = vendorId)
            HttpResponse(200, ApiSuccessResponse(data = list, correlationId = correlationId), correlationId)
        }

        request.path.startsWith("/api/v1/vendor-delivery-receipts/") && request.path.endsWith("/start") && request.method == "POST" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            BackendAuthorizationPolicy.requireRole(principal, UserRole.ADMIN, UserRole.MANAGER, UserRole.STAFF)
            val receiptId = request.path.substringAfter("/api/v1/vendor-delivery-receipts/").substringBefore("/start")
            val updated = useCases.startVendorDeliveryReceipt(principal, receiptId)
            HttpResponse(200, ApiSuccessResponse(data = updated, correlationId = correlationId), correlationId)
        }

        request.path.startsWith("/api/v1/vendor-delivery-receipts/") && request.path.endsWith("/record-received") && request.method == "POST" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            BackendAuthorizationPolicy.requireRole(principal, UserRole.ADMIN, UserRole.MANAGER, UserRole.STAFF)
            val receiptId = request.path.substringAfter("/api/v1/vendor-delivery-receipts/").substringBefore("/record-received")
            val updated = useCases.recordVendorDeliveryReceived(principal, receiptId)
            HttpResponse(200, ApiSuccessResponse(data = updated, correlationId = correlationId), correlationId)
        }

        request.path.startsWith("/api/v1/vendor-delivery-receipts/") && request.path.endsWith("/audit") && request.method == "GET" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            BackendAuthorizationPolicy.requireRole(principal, UserRole.ADMIN, UserRole.MANAGER, UserRole.STAFF)
            val receiptId = request.path.substringAfter("/api/v1/vendor-delivery-receipts/").substringBefore("/audit")
            val list = useCases.listVendorDeliveryReceiptAudits(principal, receiptId)
            HttpResponse(200, ApiSuccessResponse(data = list, correlationId = correlationId), correlationId)
        }

        request.path.startsWith("/api/v1/vendor-delivery-receipts/") && request.path.endsWith("/inspect") && request.method == "POST" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            BackendAuthorizationPolicy.requireRole(principal, UserRole.ADMIN, UserRole.MANAGER, UserRole.STAFF)
            val receiptId = request.path.substringAfter("/api/v1/vendor-delivery-receipts/").substringBefore("/inspect")
            val reqDto = when (val b = request.body) {
                is InspectVendorDeliveryReceiptRequestDto -> b
                is Map<*, *> -> InspectVendorDeliveryReceiptRequestDto(
                    items = (b["items"] as? List<*>)?.mapNotNull { itemRaw ->
                        val itemMap = itemRaw as? Map<*, *>
                        if (itemMap != null) {
                            VendorDeliveryReceiptItemDto(
                                receiptItemId = itemMap["receiptItemId"]?.toString() ?: "",
                                purchaseOrderItemId = itemMap["purchaseOrderItemId"]?.toString() ?: "",
                                acceptedQuantity = (itemMap["acceptedQuantity"] as? Number)?.toDouble() ?: 0.0,
                                rejectedQuantity = (itemMap["rejectedQuantity"] as? Number)?.toDouble() ?: 0.0,
                                damagedQuantity = (itemMap["damagedQuantity"] as? Number)?.toDouble() ?: 0.0,
                                shortQuantity = (itemMap["shortQuantity"] as? Number)?.toDouble() ?: 0.0,
                                excessQuantity = (itemMap["excessQuantity"] as? Number)?.toDouble() ?: 0.0,
                                remarks = itemMap["remarks"]?.toString()
                            )
                        } else null
                    } ?: emptyList(),
                    remarks = b["remarks"]?.toString()
                )
                else -> throw ValidationException("Request body must be a valid InspectVendorDeliveryReceiptRequestDto.")
            }
            val updated = useCases.inspectVendorDeliveryReceipt(principal, receiptId, reqDto)
            HttpResponse(200, ApiSuccessResponse(data = updated, correlationId = correlationId), correlationId)
        }

        request.path.startsWith("/api/v1/vendor-delivery-receipts/") && request.path.endsWith("/accept") && request.method == "POST" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            BackendAuthorizationPolicy.requireRole(principal, UserRole.ADMIN, UserRole.MANAGER)
            val receiptId = request.path.substringAfter("/api/v1/vendor-delivery-receipts/").substringBefore("/accept")
            val updated = useCases.acceptVendorDeliveryReceipt(principal, receiptId)
            HttpResponse(200, ApiSuccessResponse(data = updated, correlationId = correlationId), correlationId)
        }

        request.path.startsWith("/api/v1/vendor-delivery-receipts/") && request.path.endsWith("/partial-accept") && request.method == "POST" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            BackendAuthorizationPolicy.requireRole(principal, UserRole.ADMIN, UserRole.MANAGER)
            val receiptId = request.path.substringAfter("/api/v1/vendor-delivery-receipts/").substringBefore("/partial-accept")
            val remarks = when (val b = request.body) {
                is VendorDeliveryReceiptStatusChangeRequestDto -> b.remarks
                is Map<*, *> -> b["remarks"]?.toString()
                else -> null
            }
            val updated = useCases.partialAcceptVendorDeliveryReceipt(principal, receiptId, remarks)
            HttpResponse(200, ApiSuccessResponse(data = updated, correlationId = correlationId), correlationId)
        }

        request.path.startsWith("/api/v1/vendor-delivery-receipts/") && request.path.endsWith("/reject") && request.method == "POST" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            BackendAuthorizationPolicy.requireRole(principal, UserRole.ADMIN, UserRole.MANAGER)
            val receiptId = request.path.substringAfter("/api/v1/vendor-delivery-receipts/").substringBefore("/reject")
            val reason = when (val b = request.body) {
                is VendorDeliveryReceiptStatusChangeRequestDto -> b.reason ?: "Rejected by manager"
                is Map<*, *> -> b["reason"]?.toString() ?: "Rejected by manager"
                else -> "Rejected by manager"
            }
            val updated = useCases.rejectVendorDeliveryReceipt(principal, receiptId, reason)
            HttpResponse(200, ApiSuccessResponse(data = updated, correlationId = correlationId), correlationId)
        }

        request.path.startsWith("/api/v1/vendor-delivery-receipts/") && request.path.endsWith("/cancel") && request.method == "POST" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            BackendAuthorizationPolicy.requireRole(principal, UserRole.ADMIN, UserRole.MANAGER)
            val receiptId = request.path.substringAfter("/api/v1/vendor-delivery-receipts/").substringBefore("/cancel")
            val reason = when (val b = request.body) {
                is VendorDeliveryReceiptStatusChangeRequestDto -> b.reason ?: "Cancelled by user"
                is Map<*, *> -> b["reason"]?.toString() ?: "Cancelled by user"
                else -> "Cancelled by user"
            }
            val updated = useCases.cancelVendorDeliveryReceipt(principal, receiptId, reason)
            HttpResponse(200, ApiSuccessResponse(data = updated, correlationId = correlationId), correlationId)
        }

        request.path.startsWith("/api/v1/vendor-delivery-receipts/") && (request.method == "PUT" || request.method == "PATCH") -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            BackendAuthorizationPolicy.requireRole(principal, UserRole.ADMIN, UserRole.MANAGER, UserRole.STAFF)
            val receiptId = request.path.substringAfter("/api/v1/vendor-delivery-receipts/")
            val reqDto = when (val b = request.body) {
                is UpdateVendorDeliveryReceiptRequestDto -> b
