    // =========================================================================
    // 16. VENDOR INVOICE & 3-WAY MATCHING SUB-ROUTER (Step 07)
    // =========================================================================
    private suspend fun handleVendorInvoiceRoutes(request: HttpRequest, correlationId: String): HttpResponse? = when {
        request.path == "/api/v1/vendor-invoices" && request.method == "POST" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            BackendAuthorizationPolicy.requireRole(principal, UserRole.ADMIN, UserRole.MANAGER, UserRole.STAFF)
            val reqDto = when (val b = request.body) {
                is CreateVendorInvoiceRequestDto -> b
                is Map<*, *> -> CreateVendorInvoiceRequestDto(
                    vendorId = b["vendorId"]?.toString() ?: "",
                    purchaseOrderId = b["purchaseOrderId"]?.toString() ?: "",
                    vendorInvoiceNumber = b["vendorInvoiceNumber"]?.toString() ?: "",
                    invoiceDate = (b["invoiceDate"] as? Number)?.toLong() ?: System.currentTimeMillis(),
                    receivedDate = (b["receivedDate"] as? Number)?.toLong() ?: System.currentTimeMillis(),
                    currency = b["currency"]?.toString() ?: "BDT",
                    shippingAmount = (b["shippingAmount"] as? Number)?.toDouble() ?: 0.0,
                    otherCharges = (b["otherCharges"] as? Number)?.toDouble() ?: 0.0,
                    notes = b["notes"]?.toString(),
                    items = (b["items"] as? List<*>)?.mapNotNull { itemRaw ->
                        val itemMap = itemRaw as? Map<*, *>
                        if (itemMap != null) {
                            CreateVendorInvoiceItemRequestDto(
                                purchaseOrderItemId = itemMap["purchaseOrderItemId"]?.toString() ?: "",
                                deliveryReceiptItemId = itemMap["deliveryReceiptItemId"]?.toString(),
                                description = itemMap["description"]?.toString() ?: "",
                                quantity = (itemMap["quantity"] as? Number)?.toDouble() ?: 1.0,
                                unitPrice = (itemMap["unitPrice"] as? Number)?.toDouble() ?: 0.0,
                                taxRate = (itemMap["taxRate"] as? Number)?.toDouble() ?: 0.0,
                                taxAmount = (itemMap["taxAmount"] as? Number)?.toDouble() ?: 0.0,
                                discountAmount = (itemMap["discountAmount"] as? Number)?.toDouble() ?: 0.0
                            )
                        } else null
                    } ?: emptyList()
                )
                else -> throw ValidationException("Request body must be a valid CreateVendorInvoiceRequestDto.")
            }
            val created = useCases.createVendorInvoice(principal, reqDto)
            HttpResponse(201, ApiSuccessResponse(data = created, correlationId = correlationId), correlationId)
        }

        request.path.startsWith("/api/v1/vendor-invoices") && (request.path == "/api/v1/vendor-invoices" || request.path.startsWith("/api/v1/vendor-invoices?")) && request.method == "GET" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            BackendAuthorizationPolicy.requireRole(principal, UserRole.ADMIN, UserRole.MANAGER, UserRole.STAFF)
            val queryParams = if (request.path.contains("?")) {
                request.path.substringAfter("?").split("&").mapNotNull {
                    val parts = it.split("=")
                    if (parts.size == 2) parts[0] to parts[1] else null
                }.toMap()
            } else emptyMap()
            val vendorId = queryParams["vendorId"]
            val purchaseOrderId = queryParams["purchaseOrderId"]
            val status = queryParams["status"]
            val matchStatus = queryParams["matchStatus"]
            val list = useCases.listVendorInvoices(principal, vendorId, purchaseOrderId, status, matchStatus)
            HttpResponse(200, ApiSuccessResponse(data = list, correlationId = correlationId), correlationId)
        }

        request.path.startsWith("/api/v1/vendor-invoices/number/") && request.method == "GET" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            BackendAuthorizationPolicy.requireRole(principal, UserRole.ADMIN, UserRole.MANAGER, UserRole.STAFF)
            val invoiceNumber = request.path.substringAfter("/api/v1/vendor-invoices/number/")
            val invoice = useCases.getVendorInvoiceByNumber(principal, invoiceNumber)
            HttpResponse(200, ApiSuccessResponse(data = invoice, correlationId = correlationId), correlationId)
        }

        request.path.startsWith("/api/v1/vendors/") && request.path.endsWith("/invoices") && request.method == "GET" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            BackendAuthorizationPolicy.requireRole(principal, UserRole.ADMIN, UserRole.MANAGER, UserRole.STAFF)
            val vendorId = request.path.substringAfter("/api/v1/vendors/").substringBefore("/invoices")
            val list = useCases.listVendorInvoices(principal, vendorId = vendorId)
            HttpResponse(200, ApiSuccessResponse(data = list, correlationId = correlationId), correlationId)
        }

        request.path.startsWith("/api/v1/vendor-purchase-orders/") && request.path.endsWith("/invoices") && request.method == "GET" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            BackendAuthorizationPolicy.requireRole(principal, UserRole.ADMIN, UserRole.MANAGER, UserRole.STAFF)
