            HttpResponse(200, ApiSuccessResponse(data = dispute, correlationId = correlationId), correlationId)
        }


        // ==========================================
        // MODULE 17 STEP 02 - PRINTING QUOTATION
        // ==========================================

        request.path == "/api/v1/printing-quotes" && request.method == "POST" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            val reqDto = parseCreatePrintingQuoteRequest(request.body)
            val res = useCases.createPrintingQuote(principal, reqDto)
            HttpResponse(201, ApiSuccessResponse(data = res, correlationId = correlationId), correlationId)
        }

        request.path == "/api/v1/printing-quotes/calculate" && request.method == "POST" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            val reqDto = parseCalculatePrintingQuoteRequest(request.body)
            val res = useCases.calculatePrintingQuote(principal, reqDto)
            HttpResponse(200, ApiSuccessResponse(data = res, correlationId = correlationId), correlationId)
        }

        request.path == "/api/v1/printing-quotes/recalculate" && request.method == "POST" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            val reqDto = parseCalculatePrintingQuoteRequest(request.body)
            val res = useCases.recalculatePrintingQuote(principal, reqDto)
            HttpResponse(200, ApiSuccessResponse(data = res, correlationId = correlationId), correlationId)
        }

        request.path == "/api/v1/printing-quotes/review" && request.method == "POST" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            val reqDto = parseQuoteReviewRequest(request.body)
            val res = useCases.reviewPrintingQuote(principal, reqDto)
            HttpResponse(200, ApiSuccessResponse(data = res, correlationId = correlationId), correlationId)
        }

        request.path.matches(Regex("^/api/v1/printing-quotes/[^/]+/submit-review$")) && request.method == "POST" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            val id = request.path.removePrefix("/api/v1/printing-quotes/").removeSuffix("/submit-review")
            val res = useCases.submitPrintingQuoteForReview(principal, id)
            HttpResponse(200, ApiSuccessResponse(data = res, correlationId = correlationId), correlationId)
        }

        request.path.matches(Regex("^/api/v1/printing-quotes/[^/]+/reconcile$")) && request.method == "POST" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            val queryParams = parseQueryParams(request.path)
            val id = request.path.removePrefix("/api/v1/printing-quotes/").substringBefore("?").removeSuffix("/reconcile")
            val versionId = queryParams["versionId"] ?: (request.body as? Map<String, Any?>)?.get("versionId")?.toString() ?: ""
            val res = useCases.reconcilePrintingQuote(principal, id, versionId)
            HttpResponse(200, ApiSuccessResponse(data = res, correlationId = correlationId), correlationId)
        }

        request.path.matches(Regex("^/api/v1/printing-quotes/[^/]+/breakdown$")) && request.method == "GET" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            val versionId = request.path.removePrefix("/api/v1/printing-quotes/").removeSuffix("/breakdown")
            val res = useCases.getPrintingQuoteCostBreakdown(principal, versionId)
            HttpResponse(200, ApiSuccessResponse(data = res, correlationId = correlationId), correlationId)
        }

        request.path.matches(Regex("^/api/v1/printing-quotes/[^/]+/tiers$")) && request.method == "GET" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            val versionId = request.path.removePrefix("/api/v1/printing-quotes/").removeSuffix("/tiers")
            val res = useCases.getPrintingQuoteQuantityTiers(principal, versionId)
            HttpResponse(200, ApiSuccessResponse(data = res, correlationId = correlationId), correlationId)
        }

        request.path.matches(Regex("^/api/v1/printing-quotes/[^/]+/audit$")) && request.method == "GET" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            val id = request.path.removePrefix("/api/v1/printing-quotes/").removeSuffix("/audit")
            val res = useCases.getPrintingQuoteAuditTrail(principal, id)
            HttpResponse(200, ApiSuccessResponse(data = res, correlationId = correlationId), correlationId)
        }

        request.path.matches(Regex("^/api/v1/printing-quotes/[^/]+/handoff$")) && request.method == "GET" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            val id = request.path.removePrefix("/api/v1/printing-quotes/").removeSuffix("/handoff")
            val res = useCases.exportPrintingQuoteHandoffContract(principal, id)
            HttpResponse(200, ApiSuccessResponse(data = res, correlationId = correlationId), correlationId)
        }

        request.path.matches(Regex("^/api/v1/printing-quotes/[^/]+/versions$")) && request.method == "GET" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            val id = request.path.removePrefix("/api/v1/printing-quotes/").removeSuffix("/versions")
            val res = useCases.listPrintingQuoteVersions(principal, id)
            HttpResponse(200, ApiSuccessResponse(data = res, correlationId = correlationId), correlationId)
        }

        request.path.matches(Regex("^/api/v1/printing-quotes/versions/[^/]+$")) && request.method == "GET" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            val versionId = request.path.removePrefix("/api/v1/printing-quotes/versions/")
            val res = useCases.getPrintingQuoteVersion(principal, versionId)
            HttpResponse(200, ApiSuccessResponse(data = res, correlationId = correlationId), correlationId)
        }

        request.path.matches(Regex("^/api/v1/printing-quotes/[^/]+$")) && request.method == "GET" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            val id = request.path.removePrefix("/api/v1/printing-quotes/")
            val res = useCases.getPrintingQuote(principal, id)
            HttpResponse(200, ApiSuccessResponse(data = res, correlationId = correlationId), correlationId)
        }

        else -> null
    }

    // ============================================================================
    // 19. VENDOR PERFORMANCE SUB-ROUTER (Step 09)
    // ============================================================================
    private suspend fun handleVendorPerformanceRoutes(request: HttpRequest, correlationId: String): HttpResponse? = when {
        // --- KPIs ---
        (request.path == "/api/v1/vendor-performance-kpis" || request.path.endsWith("/performance/kpis")) && request.method == "POST" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            val reqDto = when (val b = request.body) {
                is CreateVendorPerformanceKpiRequestDto -> b
                is Map<*, *> -> CreateVendorPerformanceKpiRequestDto(
                    code = b["code"]?.toString() ?: "",
                    name = b["name"]?.toString() ?: "",
                    description = b["description"]?.toString() ?: "",
                    kpiType = b["kpiType"]?.toString() ?: "OPERATIONAL",
                    measurementMethod = b["measurementMethod"]?.toString() ?: "AUTOMATED",
                    targetValue = (b["targetValue"] as? Number)?.toDouble() ?: b["targetValue"]?.toString()?.toDoubleOrNull() ?: 0.0,
                    minimumAcceptableValue = (b["minimumAcceptableValue"] as? Number)?.toDouble() ?: b["minimumAcceptableValue"]?.toString()?.toDoubleOrNull(),
                    maximumAcceptableValue = (b["maximumAcceptableValue"] as? Number)?.toDouble() ?: b["maximumAcceptableValue"]?.toString()?.toDoubleOrNull(),
                    unit = b["unit"]?.toString() ?: "%",
                    direction = b["direction"]?.toString() ?: "HIGHER_IS_BETTER",
                    weight = (b["weight"] as? Number)?.toDouble() ?: b["weight"]?.toString()?.toDoubleOrNull() ?: 1.0,
                    effectiveFrom = (b["effectiveFrom"] as? Number)?.toLong() ?: b["effectiveFrom"]?.toString()?.toLongOrNull(),
                    effectiveTo = (b["effectiveTo"] as? Number)?.toLong() ?: b["effectiveTo"]?.toString()?.toLongOrNull()
                )
                is String -> {
                    val map = com.sucharu.sucharupro.data.event.serialization.EventSerializationHelper.parseJsonObject(b)
                    CreateVendorPerformanceKpiRequestDto(
                        code = map["code"] ?: "",
                        name = map["name"] ?: "",
                        description = map["description"] ?: "",
                        kpiType = map["kpiType"] ?: "OPERATIONAL",
                        measurementMethod = map["measurementMethod"] ?: "AUTOMATED",
                        targetValue = map["targetValue"]?.toDoubleOrNull() ?: 0.0,
                        minimumAcceptableValue = map["minimumAcceptableValue"]?.toDoubleOrNull(),
                        maximumAcceptableValue = map["maximumAcceptableValue"]?.toDoubleOrNull(),
                        unit = map["unit"] ?: "%",
                        direction = map["direction"] ?: "HIGHER_IS_BETTER",
                        weight = map["weight"]?.toDoubleOrNull() ?: 1.0,
                        effectiveFrom = map["effectiveFrom"]?.toLongOrNull(),
                        effectiveTo = map["effectiveTo"]?.toLongOrNull()
                    )
                }
                else -> throw ValidationException("Request body must be a valid CreateVendorPerformanceKpiRequestDto.")
            }
            val created = useCases.createVendorPerformanceKpi(principal, reqDto)
            HttpResponse(201, ApiSuccessResponse(data = created, correlationId = correlationId), correlationId)
        }

        (request.path.startsWith("/api/v1/vendor-performance-kpis") || request.path.contains("/performance/kpis")) && !request.path.contains("/measurements") && !request.path.contains("/scorecards") && request.method == "GET" && !request.path.substringAfterLast("/").startsWith("KPI-") -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            val queryParams = if (request.path.contains("?")) {
                request.path.substringAfter("?").split("&").mapNotNull {
                    val parts = it.split("=")
                    if (parts.size == 2) parts[0] to parts[1] else null
                }.toMap()
            } else emptyMap()
            val status = queryParams["status"]
            val kpiType = queryParams["kpiType"]
            val list = useCases.listVendorPerformanceKpis(principal, status, kpiType)
            HttpResponse(200, ApiSuccessResponse(data = list, correlationId = correlationId), correlationId)
        }

        request.path.startsWith("/api/v1/vendor-performance-kpis/") && request.method == "GET" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            val kpiId = request.path.substringAfter("/api/v1/vendor-performance-kpis/")
            val kpi = useCases.getVendorPerformanceKpiById(principal, kpiId)
            HttpResponse(200, ApiSuccessResponse(data = kpi, correlationId = correlationId), correlationId)
        }

        request.path.startsWith("/api/v1/vendor-performance-kpis/") && request.method == "PUT" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            val kpiId = request.path.substringAfter("/api/v1/vendor-performance-kpis/")
            val reqDto = when (val b = request.body) {
                is UpdateVendorPerformanceKpiRequestDto -> b
                is Map<*, *> -> UpdateVendorPerformanceKpiRequestDto(
                    name = b["name"]?.toString(),
                    description = b["description"]?.toString(),
                    targetValue = (b["targetValue"] as? Number)?.toDouble() ?: b["targetValue"]?.toString()?.toDoubleOrNull(),
                    minimumAcceptableValue = (b["minimumAcceptableValue"] as? Number)?.toDouble() ?: b["minimumAcceptableValue"]?.toString()?.toDoubleOrNull(),
                    maximumAcceptableValue = (b["maximumAcceptableValue"] as? Number)?.toDouble() ?: b["maximumAcceptableValue"]?.toString()?.toDoubleOrNull(),
                    weight = (b["weight"] as? Number)?.toDouble() ?: b["weight"]?.toString()?.toDoubleOrNull(),
                    status = b["status"]?.toString(),
                    effectiveTo = (b["effectiveTo"] as? Number)?.toLong() ?: b["effectiveTo"]?.toString()?.toLongOrNull()
                )
                is String -> {
                    val map = com.sucharu.sucharupro.data.event.serialization.EventSerializationHelper.parseJsonObject(b)
                    UpdateVendorPerformanceKpiRequestDto(
                        name = map["name"],
                        description = map["description"],
                        targetValue = map["targetValue"]?.toDoubleOrNull(),
                        minimumAcceptableValue = map["minimumAcceptableValue"]?.toDoubleOrNull(),
                        maximumAcceptableValue = map["maximumAcceptableValue"]?.toDoubleOrNull(),
                        weight = map["weight"]?.toDoubleOrNull(),
                        status = map["status"],
                        effectiveTo = map["effectiveTo"]?.toLongOrNull()
                    )
                }
                else -> throw ValidationException("Request body must be a valid UpdateVendorPerformanceKpiRequestDto.")
            }
            val updated = useCases.updateVendorPerformanceKpi(principal, kpiId, reqDto)
            HttpResponse(200, ApiSuccessResponse(data = updated, correlationId = correlationId), correlationId)
        }

        // --- Measurements ---
        request.path.startsWith("/api/v1/vendors/") && request.path.contains("/performance/measurements") && request.method == "POST" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            val vendorId = request.path.substringAfter("/api/v1/vendors/").substringBefore("/performance/measurements")
            val reqDto = when (val b = request.body) {
                is CreateVendorPerformanceMeasurementRequestDto -> b
                is Map<*, *> -> CreateVendorPerformanceMeasurementRequestDto(
                    kpiId = b["kpiId"]?.toString() ?: "",
                    periodStart = (b["periodStart"] as? Number)?.toLong() ?: b["periodStart"]?.toString()?.toLongOrNull() ?: 0L,
                    periodEnd = (b["periodEnd"] as? Number)?.toLong() ?: b["periodEnd"]?.toString()?.toLongOrNull() ?: 0L,
                    actualValue = (b["actualValue"] as? Number)?.toDouble() ?: b["actualValue"]?.toString()?.toDoubleOrNull() ?: 0.0,
                    numerator = (b["numerator"] as? Number)?.toDouble() ?: b["numerator"]?.toString()?.toDoubleOrNull() ?: 0.0,
                    denominator = (b["denominator"] as? Number)?.toDouble() ?: b["denominator"]?.toString()?.toDoubleOrNull() ?: 0.0,
                    unit = b["unit"]?.toString() ?: "%",
                    sampleSize = (b["sampleSize"] as? Number)?.toInt() ?: b["sampleSize"]?.toString()?.toIntOrNull() ?: 1,
                    confidenceState = b["confidenceState"]?.toString() ?: "SUFFICIENT_DATA"
                )
                is String -> {
                    val map = com.sucharu.sucharupro.data.event.serialization.EventSerializationHelper.parseJsonObject(b)
                    CreateVendorPerformanceMeasurementRequestDto(
                        kpiId = map["kpiId"] ?: "",
                        periodStart = map["periodStart"]?.toLongOrNull() ?: 0L,
                        periodEnd = map["periodEnd"]?.toLongOrNull() ?: 0L,
                        actualValue = map["actualValue"]?.toDoubleOrNull() ?: 0.0,
                        numerator = map["numerator"]?.toDoubleOrNull() ?: 0.0,
                        denominator = map["denominator"]?.toDoubleOrNull() ?: 0.0,
                        unit = map["unit"] ?: "%",
                        sampleSize = map["sampleSize"]?.toIntOrNull() ?: 1,
                        confidenceState = map["confidenceState"] ?: "SUFFICIENT_DATA"
                    )
                }
                else -> throw ValidationException("Request body must be a valid CreateVendorPerformanceMeasurementRequestDto.")
            }
            val created = useCases.recordVendorPerformanceMeasurement(principal, vendorId, reqDto)
            HttpResponse(201, ApiSuccessResponse(data = created, correlationId = correlationId), correlationId)
        }

        request.path.startsWith("/api/v1/vendors/") && request.path.contains("/performance/measurements") && request.method == "GET" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            val rawPath = request.path.substringBefore("?")
            val vendorId = rawPath.substringAfter("/api/v1/vendors/").substringBefore("/performance/measurements")
            val queryParams = if (request.path.contains("?")) {
                request.path.substringAfter("?").split("&").mapNotNull {
                    val parts = it.split("=")
                    if (parts.size == 2) parts[0] to parts[1] else null
                }.toMap()
            } else emptyMap()
            val kpiId = queryParams["kpiId"]
            val periodStart = queryParams["periodStart"]?.toLongOrNull()
            val periodEnd = queryParams["periodEnd"]?.toLongOrNull()
            val list = useCases.listVendorPerformanceMeasurements(principal, vendorId, kpiId, periodStart, periodEnd)
            HttpResponse(200, ApiSuccessResponse(data = list, correlationId = correlationId), correlationId)
        }

        // --- Scorecards ---
        request.path.startsWith("/api/v1/vendors/") && request.path.endsWith("/performance/scorecards") && request.method == "POST" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            val vendorId = request.path.substringAfter("/api/v1/vendors/").substringBefore("/performance/scorecards")
            val reqDto = when (val b = request.body) {
                is GenerateVendorPerformanceScorecardRequestDto -> b
                is Map<*, *> -> GenerateVendorPerformanceScorecardRequestDto(
                    periodType = b["periodType"]?.toString() ?: "MONTHLY",
                    periodStart = (b["periodStart"] as? Number)?.toLong() ?: b["periodStart"]?.toString()?.toLongOrNull() ?: 0L,
                    periodEnd = (b["periodEnd"] as? Number)?.toLong() ?: b["periodEnd"]?.toString()?.toLongOrNull() ?: 0L,
                    notes = b["notes"]?.toString()
                )
                is String -> {
                    val map = com.sucharu.sucharupro.data.event.serialization.EventSerializationHelper.parseJsonObject(b)
                    GenerateVendorPerformanceScorecardRequestDto(
