            } else emptyMap()
            val status = queryParams["status"]
            val list = useCases.listVendorPerformanceScorecards(principal, vendorId, status)
            HttpResponse(200, ApiSuccessResponse(data = list, correlationId = correlationId), correlationId)
        }

        request.path.startsWith("/api/v1/vendors/") && request.path.contains("/performance/scorecards/") && request.path.endsWith("/submit") && request.method == "POST" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            val scorecardId = request.path.substringAfter("/performance/scorecards/").substringBefore("/submit")
            val updated = useCases.submitVendorPerformanceScorecard(principal, scorecardId)
            HttpResponse(200, ApiSuccessResponse(data = updated, correlationId = correlationId), correlationId)
        }

        request.path.startsWith("/api/v1/vendors/") && request.path.contains("/performance/scorecards/") && request.path.endsWith("/approve") && request.method == "POST" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            val scorecardId = request.path.substringAfter("/performance/scorecards/").substringBefore("/approve")
            val updated = useCases.approveVendorPerformanceScorecard(principal, scorecardId)
            HttpResponse(200, ApiSuccessResponse(data = updated, correlationId = correlationId), correlationId)
        }

        request.path.startsWith("/api/v1/vendors/") && request.path.contains("/performance/scorecards/") && request.path.endsWith("/reject") && request.method == "POST" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            val scorecardId = request.path.substringAfter("/performance/scorecards/").substringBefore("/reject")
            val reason = when (val b = request.body) {
                is Map<*, *> -> b["reason"]?.toString() ?: "Rejected by reviewer"
                is String -> {
                    val map = com.sucharu.sucharupro.data.event.serialization.EventSerializationHelper.parseJsonObject(b)
                    map["reason"] ?: "Rejected by reviewer"
                }
                else -> "Rejected"
            }
            val updated = useCases.rejectVendorPerformanceScorecard(principal, scorecardId, reason)
            HttpResponse(200, ApiSuccessResponse(data = updated, correlationId = correlationId), correlationId)
        }

        request.path.startsWith("/api/v1/vendors/") && request.path.contains("/performance/scorecards/") && request.path.endsWith("/finalize") && request.method == "POST" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            val scorecardId = request.path.substringAfter("/performance/scorecards/").substringBefore("/finalize")
            val updated = useCases.finalizeVendorPerformanceScorecard(principal, scorecardId)
            HttpResponse(200, ApiSuccessResponse(data = updated, correlationId = correlationId), correlationId)
        }

        request.path.startsWith("/api/v1/vendors/") && request.path.contains("/performance/scorecards/") && request.method == "GET" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            val scorecardId = request.path.substringAfter("/performance/scorecards/")
            val scorecard = useCases.getVendorPerformanceScorecardById(principal, scorecardId)
            HttpResponse(200, ApiSuccessResponse(data = scorecard, correlationId = correlationId), correlationId)
