            }
            val updated = useCases.submitVendorEvaluation(principal, evaluationId, reqDto)
            HttpResponse(200, ApiSuccessResponse(data = updated, correlationId = correlationId), correlationId)
        }

        request.path.startsWith("/api/v1/vendors/") && request.path.contains("/evaluations/") && request.path.endsWith("/review") && request.method == "POST" -> {
