        request.path.startsWith("/api/v1/vendors/") && request.path.contains("/evaluations/") && request.path.endsWith("/approve") && request.method == "POST" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            val evaluationId = request.path.substringAfter("/evaluations/").substringBefore("/approve")
            val reqDto = when (val b = request.body) {
                is ApproveVendorEvaluationRequestDto -> b
