                    ApproveVendorEvaluationRequestDto(
                        decision = map["decision"] ?: "APPROVED",
                        comments = map["comments"]
                    )
                }
                else -> ApproveVendorEvaluationRequestDto()
            }
            val updated = useCases.approveVendorEvaluation(principal, evaluationId, reqDto)
            HttpResponse(200, ApiSuccessResponse(data = updated, correlationId = correlationId), correlationId)
