    // ============================================================================
    // 20. VENDOR COMPLIANCE SUB-ROUTER (Step 09)
    // ============================================================================
    private suspend fun handleVendorComplianceRoutes(request: HttpRequest, correlationId: String): HttpResponse? = when {
        // --- Requirements ---
        (request.path == "/api/v1/vendor-compliance-requirements" || request.path == "/api/v1/compliance/requirements" || request.path.endsWith("/compliance/requirements")) && request.method == "POST" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            val reqDto = when (val b = request.body) {
                is CreateVendorComplianceRequirementRequestDto -> b
                is Map<*, *> -> CreateVendorComplianceRequirementRequestDto(
                    requirementType = b["requirementType"]?.toString() ?: "TRADE_LICENSE",
                    code = b["code"]?.toString() ?: "",
                    name = b["name"]?.toString() ?: "",
                    description = b["description"]?.toString() ?: "",
                    mandatory = (b["mandatory"] as? Boolean) ?: b["mandatory"]?.toString()?.toBoolean() ?: true,
                    riskLevel = b["riskLevel"]?.toString() ?: "HIGH",
                    validityDays = (b["validityDays"] as? Number)?.toInt() ?: b["validityDays"]?.toString()?.toIntOrNull() ?: 365
                )
                is String -> {
                    val map = com.sucharu.sucharupro.data.event.serialization.EventSerializationHelper.parseJsonObject(b)
                    CreateVendorComplianceRequirementRequestDto(
                        requirementType = map["requirementType"] ?: "TRADE_LICENSE",
                        code = map["code"] ?: "",
                        name = map["name"] ?: "",
                        description = map["description"] ?: "",
                        mandatory = map["mandatory"]?.toBoolean() ?: true,
                        riskLevel = map["riskLevel"] ?: "HIGH",
                        validityDays = map["validityDays"]?.toIntOrNull() ?: 365
                    )
                }
                else -> throw ValidationException("Request body must be a valid CreateVendorComplianceRequirementRequestDto.")
            }
            val created = useCases.createVendorComplianceRequirement(principal, reqDto)
            HttpResponse(201, ApiSuccessResponse(data = created, correlationId = correlationId), correlationId)
        }

        (request.path == "/api/v1/vendor-compliance-requirements" || request.path == "/api/v1/compliance/requirements" || request.path.endsWith("/compliance/requirements")) && request.method == "GET" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            val queryParams = if (request.path.contains("?")) {
                request.path.substringAfter("?").split("&").mapNotNull {
                    val parts = it.split("=")
                    if (parts.size == 2) parts[0] to parts[1] else null
                }.toMap()
            } else emptyMap()
            val status = queryParams["status"]
            val list = useCases.listVendorComplianceRequirements(principal, status)
            HttpResponse(200, ApiSuccessResponse(data = list, correlationId = correlationId), correlationId)
        }

        request.path.startsWith("/api/v1/vendor-compliance-requirements/") && request.method == "GET" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            val reqId = request.path.substringAfter("/api/v1/vendor-compliance-requirements/")
            val req = useCases.getVendorComplianceRequirementById(principal, reqId)
            HttpResponse(200, ApiSuccessResponse(data = req, correlationId = correlationId), correlationId)
        }

        // --- Records ---
        request.path.startsWith("/api/v1/vendors/") && request.path.endsWith("/compliance/records") && request.method == "POST" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            val vendorId = request.path.substringAfter("/api/v1/vendors/").substringBefore("/compliance/records")
            val reqDto = when (val b = request.body) {
                is SubmitVendorComplianceRecordRequestDto -> b
                is Map<*, *> -> SubmitVendorComplianceRecordRequestDto(
                    requirementId = b["requirementId"]?.toString() ?: "",
                    effectiveDate = (b["effectiveDate"] as? Number)?.toLong() ?: b["effectiveDate"]?.toString()?.toLongOrNull(),
                    expiryDate = (b["expiryDate"] as? Number)?.toLong() ?: b["expiryDate"]?.toString()?.toLongOrNull(),
                    notes = b["notes"]?.toString()
                )
                is String -> {
                    val map = com.sucharu.sucharupro.data.event.serialization.EventSerializationHelper.parseJsonObject(b)
                    SubmitVendorComplianceRecordRequestDto(
                        requirementId = map["requirementId"] ?: "",
                        effectiveDate = map["effectiveDate"]?.toLongOrNull(),
                        expiryDate = map["expiryDate"]?.toLongOrNull(),
                        notes = map["notes"]
                    )
                }
                else -> throw ValidationException("Request body must be a valid SubmitVendorComplianceRecordRequestDto.")
            }
            val record = useCases.submitVendorComplianceRecord(principal, vendorId, reqDto)
            HttpResponse(201, ApiSuccessResponse(data = record, correlationId = correlationId), correlationId)
        }

        request.path.startsWith("/api/v1/vendors/") && (request.path.endsWith("/compliance/records") || request.path.contains("/compliance/records?")) && request.method == "GET" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            val rawPath = request.path.substringBefore("?")
            val vendorId = rawPath.substringAfter("/api/v1/vendors/").substringBefore("/compliance/records")
            val queryParams = if (request.path.contains("?")) {
                request.path.substringAfter("?").split("&").mapNotNull {
                    val parts = it.split("=")
                    if (parts.size == 2) parts[0] to parts[1] else null
                }.toMap()
            } else emptyMap()
            val status = queryParams["status"]
            val list = useCases.listVendorComplianceRecords(principal, vendorId, status)
            HttpResponse(200, ApiSuccessResponse(data = list, correlationId = correlationId), correlationId)
        }

        request.path.startsWith("/api/v1/vendors/") && request.path.contains("/compliance/records/") && request.path.endsWith("/verify") && request.method == "POST" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            val recordId = request.path.substringAfter("/compliance/records/").substringBefore("/verify")
            val reqDto = when (val b = request.body) {
                is VerifyVendorComplianceRecordRequestDto -> b
                is Map<*, *> -> VerifyVendorComplianceRecordRequestDto(
                    verified = (b["verified"] as? Boolean) ?: b["verified"]?.toString()?.toBoolean() ?: true,
                    rejectionReason = b["rejectionReason"]?.toString(),
                    notes = b["notes"]?.toString()
                )
                is String -> {
                    val map = com.sucharu.sucharupro.data.event.serialization.EventSerializationHelper.parseJsonObject(b)
                    VerifyVendorComplianceRecordRequestDto(
                        verified = map["verified"]?.toBoolean() ?: true,
                        rejectionReason = map["rejectionReason"],
                        notes = map["notes"]
                    )
                }
                else -> VerifyVendorComplianceRecordRequestDto()
            }
            val updated = useCases.verifyVendorComplianceRecord(principal, recordId, reqDto)
            HttpResponse(200, ApiSuccessResponse(data = updated, correlationId = correlationId), correlationId)
        }

        request.path.startsWith("/api/v1/vendors/") && request.path.contains("/compliance/") && request.path.endsWith("/verify") && request.method == "POST" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            val recordId = request.path.substringAfter("/compliance/").substringBefore("/verify")
            val updated = useCases.verifyVendorComplianceRecord(principal, recordId, VerifyVendorComplianceRecordRequestDto(verified = true))
            HttpResponse(200, ApiSuccessResponse(data = updated, correlationId = correlationId), correlationId)
        }

        request.path.startsWith("/api/v1/vendors/") && request.path.contains("/compliance/") && request.path.endsWith("/reject") && request.method == "POST" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            val recordId = request.path.substringAfter("/compliance/").substringBefore("/reject")
            val reason = when (val b = request.body) {
                is Map<*, *> -> b["reason"]?.toString() ?: "Rejected compliance document"
                is String -> {
                    val map = com.sucharu.sucharupro.data.event.serialization.EventSerializationHelper.parseJsonObject(b)
                    map["reason"] ?: "Rejected compliance document"
                }
                else -> "Rejected"
            }
            val updated = useCases.verifyVendorComplianceRecord(principal, recordId, VerifyVendorComplianceRecordRequestDto(verified = false, rejectionReason = reason))
            HttpResponse(200, ApiSuccessResponse(data = updated, correlationId = correlationId), correlationId)
        }

        request.path.startsWith("/api/v1/vendors/") && request.path.endsWith("/compliance/evaluate-expiries") && request.method == "POST" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
