            val list = useCases.evaluateVendorComplianceExpiries(principal, vendorId)
            HttpResponse(200, ApiSuccessResponse(data = list, correlationId = correlationId), correlationId)
        }

        request.path.startsWith("/api/v1/vendors/") && request.path.contains("/compliance/records/") && request.method == "GET" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            val recordId = request.path.substringAfter("/compliance/records/")
            val record = useCases.getVendorComplianceRecordById(principal, recordId)
            HttpResponse(200, ApiSuccessResponse(data = record, correlationId = correlationId), correlationId)
        }


        // ==========================================
        // MODULE 17 STEP 02 - PRINTING QUOTATION
        // ==========================================

        request.path == "/api/v1/printing-quotes" && request.method == "POST" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
