    // 21. VENDOR PORTAL FOUNDATION & ACCESS SUB-ROUTER (Module 13 Step 01)
    // =========================================================================
    private suspend fun handleVendorPortalRoutes(request: HttpRequest, correlationId: String): HttpResponse? {
        return handleVendorPortalBaseRoutes(request, correlationId)
            ?: handleVendorPortalOperationsRoutes(request, correlationId)
            ?: handleVendorPortalSettlementRoutes(request, correlationId)
    }

