                    evidenceReferences = (b["evidenceReferences"] as? List<*>)?.mapNotNull { it?.toString() } ?: emptyList()
                )
                else -> throw ValidationException("Request body must be a valid SubmitCompletionRequestDto.")
            }
            val compl = useCases.submitVendorPortalCompletionRequest(principal, workOrderId, reqDto)
            HttpResponse(201, ApiSuccessResponse(data = compl, correlationId = correlationId), correlationId)
        }

        request.path.startsWith("/api/v1/vendor-portal/work-orders/") && request.path.endsWith("/completion-request") && request.method == "GET" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            val workOrderId = request.path.substringAfter("/api/v1/vendor-portal/work-orders/").substringBefore("/completion-request")
            val compl = useCases.getVendorPortalCompletionRequest(principal, workOrderId)
            HttpResponse(200, ApiSuccessResponse(data = compl, correlationId = correlationId), correlationId)
        }

        request.path.startsWith("/api/v1/vendor-portal/work-orders/") && request.path.endsWith("/collaboration-audit") && request.method == "GET" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            val workOrderId = request.path.substringAfter("/api/v1/vendor-portal/work-orders/").substringBefore("/collaboration-audit")
            val audits = useCases.listVendorPortalCollaborationAuditEvents(principal, "WORK_ORDER", workOrderId)
            HttpResponse(200, ApiSuccessResponse(data = audits, correlationId = correlationId), correlationId)
        }

        request.path.startsWith("/api/v1/vendor-portal/work-orders/") && !request.path.substringAfter("/api/v1/vendor-portal/work-orders/").contains("/") && request.method == "GET" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            val workOrderId = request.path.substringAfter("/api/v1/vendor-portal/work-orders/")
            val wo = useCases.getVendorPortalWorkOrderDetails(principal, workOrderId)
            HttpResponse(200, ApiSuccessResponse(data = wo, correlationId = correlationId), correlationId)
        }

        // --- Blockers ---

        (request.path == "/api/v1/vendor-portal/blockers" || request.path.startsWith("/api/v1/vendor-portal/blockers?")) && request.method == "GET" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            val queryParams = if (request.path.contains("?")) {
                request.path.substringAfter("?").split("&").mapNotNull {
                    val parts = it.split("=")
                    if (parts.size == 2) parts[0] to parts[1] else null
                }.toMap()
            } else emptyMap()
            val list = useCases.listVendorPortalBlockers(principal, queryParams["workOrderId"], queryParams["status"])
            HttpResponse(200, ApiSuccessResponse(data = list, correlationId = correlationId), correlationId)
        }

        request.path.startsWith("/api/v1/vendor-portal/blockers/") && request.path.endsWith("/acknowledge") && request.method == "POST" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            val blockerId = request.path.substringAfter("/api/v1/vendor-portal/blockers/").substringBefore("/acknowledge")
            val updated = useCases.acknowledgeVendorPortalBlocker(principal, blockerId)
            HttpResponse(200, ApiSuccessResponse(data = updated, correlationId = correlationId), correlationId)
        }

        request.path.startsWith("/api/v1/vendor-portal/blockers/") && request.path.endsWith("/resolve") && request.method == "POST" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            val blockerId = request.path.substringAfter("/api/v1/vendor-portal/blockers/").substringBefore("/resolve")
            val reqDto = when (val b = request.body) {
                is ResolveBlockerRequestDto -> b
                is Map<*, *> -> ResolveBlockerRequestDto(resolutionNotes = b["resolutionNotes"]?.toString() ?: "")
                else -> throw ValidationException("Request body must be a valid ResolveBlockerRequestDto.")
            }
            val updated = useCases.resolveVendorPortalBlocker(principal, blockerId, reqDto)
            HttpResponse(200, ApiSuccessResponse(data = updated, correlationId = correlationId), correlationId)
        }

        // --- Threads & Messages ---

        request.path == "/api/v1/vendor-portal/threads" && request.method == "POST" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            val reqDto = when (val b = request.body) {
                is CreateCollaborationThreadRequestDto -> b
                is Map<*, *> -> CreateCollaborationThreadRequestDto(
                    resourceType = b["resourceType"]?.toString() ?: "",
                    resourceId = b["resourceId"]?.toString() ?: "",
                    title = b["title"]?.toString() ?: ""
                )
                else -> throw ValidationException("Request body must be a valid CreateCollaborationThreadRequestDto.")
            }
            val thread = useCases.getOrCreateVendorPortalThread(principal, reqDto)
            HttpResponse(201, ApiSuccessResponse(data = thread, correlationId = correlationId), correlationId)
        }

        request.path.startsWith("/api/v1/vendor-portal/threads/") && request.path.endsWith("/messages") && request.method == "POST" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            val threadId = request.path.substringAfter("/api/v1/vendor-portal/threads/").substringBefore("/messages")
            val reqDto = when (val b = request.body) {
                is PostCollaborationMessageRequestDto -> b
                is Map<*, *> -> PostCollaborationMessageRequestDto(
                    message = b["message"]?.toString() ?: "",
                    visibility = b["visibility"]?.toString() ?: "VENDOR_VISIBLE",
                    attachmentMetadataJson = b["attachmentMetadataJson"]?.toString()
                )
                else -> throw ValidationException("Request body must be a valid PostCollaborationMessageRequestDto.")
            }
            val message = useCases.postVendorPortalCollaborationMessage(principal, threadId, reqDto)
            HttpResponse(201, ApiSuccessResponse(data = message, correlationId = correlationId), correlationId)
        }

        request.path.startsWith("/api/v1/vendor-portal/threads/") && request.path.endsWith("/messages") && request.method == "GET" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            val threadId = request.path.substringAfter("/api/v1/vendor-portal/threads/").substringBefore("/messages")
            val list = useCases.listVendorPortalCollaborationMessages(principal, threadId)
            HttpResponse(200, ApiSuccessResponse(data = list, correlationId = correlationId), correlationId)
        }

        // --- Evidence Metadata ---

        request.path == "/api/v1/vendor-portal/evidence" && request.method == "POST" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            val reqDto = when (val b = request.body) {
                is RegisterCollaborationEvidenceRequestDto -> b
                is Map<*, *> -> RegisterCollaborationEvidenceRequestDto(
                    resourceType = b["resourceType"]?.toString() ?: "",
                    resourceId = b["resourceId"]?.toString() ?: "",
                    fileReference = b["fileReference"]?.toString() ?: "",
                    filename = b["filename"]?.toString() ?: "",
                    mimeType = b["mimeType"]?.toString() ?: "application/octet-stream",
                    sizeBytes = (b["sizeBytes"] as? Number)?.toLong() ?: 0L,
                    description = b["description"]?.toString(),
                    visibility = b["visibility"]?.toString() ?: "VENDOR_VISIBLE"
                )
                else -> throw ValidationException("Request body must be a valid RegisterCollaborationEvidenceRequestDto.")
            }
            val evidence = useCases.registerVendorPortalEvidence(principal, reqDto)
            HttpResponse(201, ApiSuccessResponse(data = evidence, correlationId = correlationId), correlationId)
        }

        // --- Completion Requests ---

        request.path.startsWith("/api/v1/vendor-portal/completion-requests/") && request.path.endsWith("/review") && request.method == "POST" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            val workOrderId = request.path.substringAfter("/api/v1/vendor-portal/completion-requests/").substringBefore("/review")
            val reqDto = when (val b = request.body) {
                is ReviewCompletionRequestDto -> b
                is Map<*, *> -> ReviewCompletionRequestDto(
                    approved = b["approved"] as? Boolean ?: true,
                    reviewNotes = b["reviewNotes"]?.toString()
                )
                else -> throw ValidationException("Request body must be a valid ReviewCompletionRequestDto.")
            }
            val reviewed = useCases.reviewVendorPortalCompletionRequest(principal, workOrderId, reqDto)
            HttpResponse(200, ApiSuccessResponse(data = reviewed, correlationId = correlationId), correlationId)
        }


        // ==========================================
        // MODULE 17 STEP 02 - PRINTING QUOTATION
        // ==========================================

        request.path == "/api/v1/printing-quotes" && request.method == "POST" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            val reqDto = parseCreatePrintingQuoteRequest(request.body)
            val res = useCases.createPrintingQuote(principal, reqDto)
            HttpResponse(201, ApiSuccessResponse(data = res, correlationId = correlationId), correlationId)
        }

        request.path == "/api/v1/printing-quotes/calculate" && request.method == "POST" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            val reqDto = parseCalculatePrintingQuoteRequest(request.body)
            val res = useCases.calculatePrintingQuote(principal, reqDto)
            HttpResponse(200, ApiSuccessResponse(data = res, correlationId = correlationId), correlationId)
        }

        request.path == "/api/v1/printing-quotes/recalculate" && request.method == "POST" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            val reqDto = parseCalculatePrintingQuoteRequest(request.body)
            val res = useCases.recalculatePrintingQuote(principal, reqDto)
            HttpResponse(200, ApiSuccessResponse(data = res, correlationId = correlationId), correlationId)
        }

        request.path == "/api/v1/printing-quotes/review" && request.method == "POST" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            val reqDto = parseQuoteReviewRequest(request.body)
            val res = useCases.reviewPrintingQuote(principal, reqDto)
            HttpResponse(200, ApiSuccessResponse(data = res, correlationId = correlationId), correlationId)
        }

        request.path.matches(Regex("^/api/v1/printing-quotes/[^/]+/submit-review$")) && request.method == "POST" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            val id = request.path.removePrefix("/api/v1/printing-quotes/").removeSuffix("/submit-review")
            val res = useCases.submitPrintingQuoteForReview(principal, id)
            HttpResponse(200, ApiSuccessResponse(data = res, correlationId = correlationId), correlationId)
        }

        request.path.matches(Regex("^/api/v1/printing-quotes/[^/]+/reconcile$")) && request.method == "POST" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            val queryParams = parseQueryParams(request.path)
            val id = request.path.removePrefix("/api/v1/printing-quotes/").substringBefore("?").removeSuffix("/reconcile")
            val versionId = queryParams["versionId"] ?: (request.body as? Map<String, Any?>)?.get("versionId")?.toString() ?: ""
            val res = useCases.reconcilePrintingQuote(principal, id, versionId)
            HttpResponse(200, ApiSuccessResponse(data = res, correlationId = correlationId), correlationId)
        }

        request.path.matches(Regex("^/api/v1/printing-quotes/[^/]+/breakdown$")) && request.method == "GET" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            val versionId = request.path.removePrefix("/api/v1/printing-quotes/").removeSuffix("/breakdown")
            val res = useCases.getPrintingQuoteCostBreakdown(principal, versionId)
            HttpResponse(200, ApiSuccessResponse(data = res, correlationId = correlationId), correlationId)
        }

        request.path.matches(Regex("^/api/v1/printing-quotes/[^/]+/tiers$")) && request.method == "GET" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            val versionId = request.path.removePrefix("/api/v1/printing-quotes/").removeSuffix("/tiers")
            val res = useCases.getPrintingQuoteQuantityTiers(principal, versionId)
            HttpResponse(200, ApiSuccessResponse(data = res, correlationId = correlationId), correlationId)
        }

        request.path.matches(Regex("^/api/v1/printing-quotes/[^/]+/audit$")) && request.method == "GET" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            val id = request.path.removePrefix("/api/v1/printing-quotes/").removeSuffix("/audit")
            val res = useCases.getPrintingQuoteAuditTrail(principal, id)
            HttpResponse(200, ApiSuccessResponse(data = res, correlationId = correlationId), correlationId)
        }

        request.path.matches(Regex("^/api/v1/printing-quotes/[^/]+/handoff$")) && request.method == "GET" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            val id = request.path.removePrefix("/api/v1/printing-quotes/").removeSuffix("/handoff")
            val res = useCases.exportPrintingQuoteHandoffContract(principal, id)
            HttpResponse(200, ApiSuccessResponse(data = res, correlationId = correlationId), correlationId)
        }

        request.path.matches(Regex("^/api/v1/printing-quotes/[^/]+/versions$")) && request.method == "GET" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            val id = request.path.removePrefix("/api/v1/printing-quotes/").removeSuffix("/versions")
            val res = useCases.listPrintingQuoteVersions(principal, id)
            HttpResponse(200, ApiSuccessResponse(data = res, correlationId = correlationId), correlationId)
        }

        request.path.matches(Regex("^/api/v1/printing-quotes/versions/[^/]+$")) && request.method == "GET" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            val versionId = request.path.removePrefix("/api/v1/printing-quotes/versions/")
            val res = useCases.getPrintingQuoteVersion(principal, versionId)
            HttpResponse(200, ApiSuccessResponse(data = res, correlationId = correlationId), correlationId)
        }

        request.path.matches(Regex("^/api/v1/printing-quotes/[^/]+$")) && request.method == "GET" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            val id = request.path.removePrefix("/api/v1/printing-quotes/")
            val res = useCases.getPrintingQuote(principal, id)
            HttpResponse(200, ApiSuccessResponse(data = res, correlationId = correlationId), correlationId)
        }

        else -> null
    }

    // =========================================================================
    // MODULE 13 STEPS 05 - 08: OPERATIONS, DELIVERY & QUALITY SUB-ROUTER
    // =========================================================================
    private suspend fun handleVendorPortalOperationsRoutes(request: HttpRequest, correlationId: String): HttpResponse? = when {
        // --- Delivery Notices (ASN) ---

        request.path == "/api/v1/vendor-portal/delivery-notices" && request.method == "POST" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            val reqDto = when (val b = request.body) {
                is CreateDeliveryNoticeRequestDto -> b
                is Map<*, *> -> {
                    val rawItems = (b["items"] as? List<*>) ?: emptyList<Any>()
                    val parsedItems = rawItems.map { rawItem ->
                        val itemMap = rawItem as? Map<*, *> ?: emptyMap<String, Any>()
                        CreateDeliveryNoticeItemRequestDto(
                            purchaseOrderItemId = itemMap["purchaseOrderItemId"]?.toString() ?: "",
                            deliveryQuantity = (itemMap["deliveryQuantity"] as? Number)?.toDouble() ?: 0.0,
                            lotNumber = itemMap["lotNumber"]?.toString(),
                            packageCount = (itemMap["packageCount"] as? Number)?.toInt(),
                            remarks = itemMap["remarks"]?.toString()
                        )
                    }
                    CreateDeliveryNoticeRequestDto(
                        purchaseOrderId = b["purchaseOrderId"]?.toString() ?: "",
                        plannedDeliveryDate = (b["plannedDeliveryDate"] as? Number)?.toLong() ?: System.currentTimeMillis(),
                        carrierName = b["carrierName"]?.toString(),
                        trackingNumber = b["trackingNumber"]?.toString(),
                        vehicleNumber = b["vehicleNumber"]?.toString(),
                        driverName = b["driverName"]?.toString(),
                        driverPhone = b["driverPhone"]?.toString(),
                        vendorNotes = b["vendorNotes"]?.toString(),
                        items = parsedItems
                    )
                }
                else -> throw ValidationException("Request body must be a valid CreateDeliveryNoticeRequestDto.")
            }
            val notice = useCases.createVendorPortalDeliveryNotice(principal, reqDto)
            HttpResponse(201, ApiSuccessResponse(data = notice, correlationId = correlationId), correlationId)
        }

        (request.path == "/api/v1/vendor-portal/delivery-notices" || request.path.startsWith("/api/v1/vendor-portal/delivery-notices?")) && request.method == "GET" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            val queryParams = if (request.path.contains("?")) {
                request.path.substringAfter("?").split("&").mapNotNull {
                    val parts = it.split("=")
                    if (parts.size == 2) parts[0] to parts[1] else null
                }.toMap()
            } else emptyMap()
            val poId = queryParams["purchaseOrderId"]
            val status = queryParams["status"]
            val notices = useCases.listVendorPortalDeliveryNotices(principal, poId, status)
            HttpResponse(200, ApiSuccessResponse(data = notices, correlationId = correlationId), correlationId)
        }

        request.path.startsWith("/api/v1/vendor-portal/delivery-notices/") && request.path.endsWith("/submit") && request.method == "POST" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            val noticeId = request.path.substringAfter("/api/v1/vendor-portal/delivery-notices/").substringBefore("/submit")
            val submitted = useCases.submitVendorPortalDeliveryNotice(principal, noticeId)
            HttpResponse(200, ApiSuccessResponse(data = submitted, correlationId = correlationId), correlationId)
        }

        request.path.startsWith("/api/v1/vendor-portal/delivery-notices/") && request.path.endsWith("/cancel") && request.method == "POST" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            val noticeId = request.path.substringAfter("/api/v1/vendor-portal/delivery-notices/").substringBefore("/cancel")
            val reqDto = when (val b = request.body) {
                is CancelDeliveryNoticeRequestDto -> b
                is Map<*, *> -> CancelDeliveryNoticeRequestDto(
                    reason = b["reason"]?.toString() ?: "Vendor cancellation"
                )
                else -> throw ValidationException("Request body must be a valid CancelDeliveryNoticeRequestDto.")
            }
            val cancelled = useCases.cancelVendorPortalDeliveryNotice(principal, noticeId, reqDto)
            HttpResponse(200, ApiSuccessResponse(data = cancelled, correlationId = correlationId), correlationId)
        }

        request.path.startsWith("/api/v1/vendor-portal/delivery-notices/") && request.method == "GET" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            val noticeId = request.path.removePrefix("/api/v1/vendor-portal/delivery-notices/")
            val notice = useCases.getVendorPortalDeliveryNotice(principal, noticeId)
            HttpResponse(200, ApiSuccessResponse(data = notice, correlationId = correlationId), correlationId)
        }

        request.path.startsWith("/api/v1/vendor-portal/delivery-notices/") && request.method == "PUT" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            val noticeId = request.path.removePrefix("/api/v1/vendor-portal/delivery-notices/")
            val reqDto = when (val b = request.body) {
                is UpdateDeliveryNoticeRequestDto -> b
                is Map<*, *> -> UpdateDeliveryNoticeRequestDto(
                    plannedDeliveryDate = (b["plannedDeliveryDate"] as? Number)?.toLong() ?: System.currentTimeMillis(),
                    carrierName = b["carrierName"]?.toString(),
                    trackingNumber = b["trackingNumber"]?.toString(),
                    vehicleNumber = b["vehicleNumber"]?.toString(),
                    driverName = b["driverName"]?.toString(),
                    driverPhone = b["driverPhone"]?.toString(),
                    vendorNotes = b["vendorNotes"]?.toString()
                )
                else -> throw ValidationException("Request body must be a valid UpdateDeliveryNoticeRequestDto.")
            }
            val updated = useCases.updateVendorPortalDeliveryNotice(principal, noticeId, reqDto)
            HttpResponse(200, ApiSuccessResponse(data = updated, correlationId = correlationId), correlationId)
        }

        // --- Receiving Summary Projection ---

        request.path.startsWith("/api/v1/vendor-portal/purchase-orders/") && request.path.endsWith("/receiving") && request.method == "GET" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            val poId = request.path.substringAfter("/api/v1/vendor-portal/purchase-orders/").substringBefore("/receiving")
            val receivingSummary = useCases.getVendorPortalPurchaseOrderReceivingSummary(principal, poId)
            HttpResponse(200, ApiSuccessResponse(data = receivingSummary, correlationId = correlationId), correlationId)
        }

        request.path.startsWith("/api/v1/vendor-portal/delivery-receipts/") && request.method == "GET" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            val receiptId = request.path.removePrefix("/api/v1/vendor-portal/delivery-receipts/")
            val receipt = useCases.getVendorPortalDeliveryReceiptDetails(principal, receiptId)
            HttpResponse(200, ApiSuccessResponse(data = receipt, correlationId = correlationId), correlationId)
        }

        // --- Quality Collaboration ---

        (request.path == "/api/v1/vendor-portal/quality-inspections" || request.path.startsWith("/api/v1/vendor-portal/quality-inspections?")) && request.method == "GET" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            val queryParams = if (request.path.contains("?")) {
                request.path.substringAfter("?").split("&").mapNotNull {
                    val parts = it.split("=")
                    if (parts.size == 2) parts[0] to parts[1] else null
                }.toMap()
            } else emptyMap()
            val receiptId = queryParams["deliveryReceiptId"]
            val inspections = useCases.listVendorPortalQualityInspections(principal, receiptId)
            HttpResponse(200, ApiSuccessResponse(data = inspections, correlationId = correlationId), correlationId)
        }

        request.path.startsWith("/api/v1/vendor-portal/quality-inspections/") && request.path.endsWith("/acknowledge") && request.method == "POST" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            val inspectionId = request.path.substringAfter("/api/v1/vendor-portal/quality-inspections/").substringBefore("/acknowledge")
            val reqDto = when (val b = request.body) {
                is AcknowledgeQualityInspectionRequestDto -> b
                is Map<*, *> -> AcknowledgeQualityInspectionRequestDto(
                    comment = b["comment"]?.toString() ?: "Quality inspection findings acknowledged"
                )
                else -> throw ValidationException("Request body must be a valid AcknowledgeQualityInspectionRequestDto.")
            }
            val ack = useCases.acknowledgeVendorPortalQualityInspection(principal, inspectionId, reqDto)
            HttpResponse(200, ApiSuccessResponse(data = ack, correlationId = correlationId), correlationId)
        }

        request.path.startsWith("/api/v1/vendor-portal/quality-inspections/") && request.path.endsWith("/respond") && request.method == "POST" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            val inspectionId = request.path.substringAfter("/api/v1/vendor-portal/quality-inspections/").substringBefore("/respond")
            val reqDto = when (val b = request.body) {
                is RespondQualityRequestDto -> b
                is Map<*, *> -> RespondQualityRequestDto(
                    rejectionId = b["rejectionId"]?.toString(),
                    responseType = b["responseType"]?.toString() ?: "ACKNOWLEDGE",
                    comment = b["comment"]?.toString() ?: "",
                    correctiveActionPlan = b["correctiveActionPlan"]?.toString(),
                    promisedReplacementDate = (b["promisedReplacementDate"] as? Number)?.toLong(),
                    evidenceReferences = (b["evidenceReferences"] as? List<*>)?.mapNotNull { it?.toString() } ?: emptyList()
                )
                else -> throw ValidationException("Request body must be a valid RespondQualityRequestDto.")
            }
            val resp = useCases.respondVendorPortalQuality(principal, inspectionId, reqDto)
            HttpResponse(200, ApiSuccessResponse(data = resp, correlationId = correlationId), correlationId)
        }

        request.path.startsWith("/api/v1/vendor-portal/quality-inspections/") && request.method == "GET" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            val inspectionId = request.path.removePrefix("/api/v1/vendor-portal/quality-inspections/")
            val inspection = useCases.getVendorPortalQualityInspectionDetails(principal, inspectionId)
            HttpResponse(200, ApiSuccessResponse(data = inspection, correlationId = correlationId), correlationId)
        }

        // --- Delivery Exceptions ---

        (request.path == "/api/v1/vendor-portal/delivery-exceptions" || request.path.startsWith("/api/v1/vendor-portal/delivery-exceptions?")) && request.method == "GET" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            val queryParams = if (request.path.contains("?")) {
                request.path.substringAfter("?").split("&").mapNotNull {
                    val parts = it.split("=")
                    if (parts.size == 2) parts[0] to parts[1] else null
                }.toMap()
            } else emptyMap()
            val status = queryParams["status"]
            val sourceType = queryParams["sourceType"]
            val exceptions = useCases.listVendorPortalDeliveryExceptions(principal, status, sourceType)
            HttpResponse(200, ApiSuccessResponse(data = exceptions, correlationId = correlationId), correlationId)
        }

        request.path.startsWith("/api/v1/vendor-portal/delivery-exceptions/") && request.path.endsWith("/resolve") && request.method == "POST" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            val exceptionId = request.path.substringAfter("/api/v1/vendor-portal/delivery-exceptions/").substringBefore("/resolve")
            val reqDto = when (val b = request.body) {
                is ResolveDeliveryExceptionRequestDto -> b
                is Map<*, *> -> ResolveDeliveryExceptionRequestDto(
                    resolutionNotes = b["resolutionNotes"]?.toString() ?: "Exception resolved"
                )
                else -> throw ValidationException("Request body must be a valid ResolveDeliveryExceptionRequestDto.")
            }
            val resolved = useCases.resolveVendorPortalDeliveryException(principal, exceptionId, reqDto)
            HttpResponse(200, ApiSuccessResponse(data = resolved, correlationId = correlationId), correlationId)
        }

        // --- Evidence & Audit ---

        request.path == "/api/v1/vendor-portal/delivery-evidence" && request.method == "POST" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
