    // =========================================================================
    // 21. VENDOR PORTAL SETTLEMENT, RECONCILIATION & FINANCIAL COLLABORATION (Module 13 Step 09)
    // =========================================================================
    private suspend fun handleVendorPortalSettlementRoutes(request: HttpRequest, correlationId: String): HttpResponse? = when {
        request.path == "/api/v1/vendor-portal/settlements" && request.method == "GET" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            val settlements = useCases.listVendorPortalSettlements(principal)
            HttpResponse(200, ApiSuccessResponse(data = settlements, correlationId = correlationId), correlationId)
        }

        request.path.startsWith("/api/v1/vendor-portal/settlements/") && request.path.endsWith("/allocations") && request.method == "GET" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            val settlementId = request.path.substringAfter("/api/v1/vendor-portal/settlements/").substringBefore("/allocations")
            val allocations = useCases.getVendorPortalSettlementAllocations(principal, settlementId)
            HttpResponse(200, ApiSuccessResponse(data = allocations, correlationId = correlationId), correlationId)
        }

        request.path.startsWith("/api/v1/vendor-portal/settlements/") && request.path.endsWith("/acknowledge") && request.method == "POST" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            val settlementId = request.path.substringAfter("/api/v1/vendor-portal/settlements/").substringBefore("/acknowledge")
            val reqDto = when (val b = request.body) {
                is VendorPortalSettlementAcknowledgementRequest -> b
                is Map<*, *> -> {
                    val rawRefs = (b["evidenceReferences"] as? List<*>) ?: emptyList<Any>()
                    val parsedRefs = rawRefs.mapNotNull { it?.toString() }
                    VendorPortalSettlementAcknowledgementRequest(
                        status = b["status"]?.toString() ?: "ACKNOWLEDGED",
                        idempotencyKey = b["idempotencyKey"]?.toString() ?: "",
                        discrepancyFlag = b["discrepancyFlag"] as? Boolean ?: false,
                        discrepancyNotes = b["discrepancyNotes"]?.toString(),
                        evidenceReferences = parsedRefs
                    )
                }
                else -> throw ValidationException("Request body must be a valid VendorPortalSettlementAcknowledgementRequest.")
            }
            val ack = useCases.acknowledgeVendorPortalSettlement(principal, settlementId, reqDto)
            HttpResponse(200, ApiSuccessResponse(data = ack, correlationId = correlationId), correlationId)
        }

        request.path.startsWith("/api/v1/vendor-portal/settlements/") && request.method == "GET" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            val settlementId = request.path.substringAfter("/api/v1/vendor-portal/settlements/")
            val settlement = useCases.getVendorPortalSettlementById(principal, settlementId)
            HttpResponse(200, ApiSuccessResponse(data = settlement, correlationId = correlationId), correlationId)
        }

        request.path.startsWith("/api/v1/vendor-portal/reconciliation/") && request.path.endsWith("/respond") && request.method == "POST" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            val caseId = request.path.substringAfter("/api/v1/vendor-portal/reconciliation/").substringBefore("/respond")
            val reqDto = when (val b = request.body) {
                is VendorPortalReconciliationResponseRequest -> b
                is Map<*, *> -> VendorPortalReconciliationResponseRequest(
                    remarks = b["remarks"]?.toString() ?: ""
                )
                else -> throw ValidationException("Request body must be a valid VendorPortalReconciliationResponseRequest.")
            }
            val case = useCases.respondToVendorPortalReconciliation(principal, caseId, reqDto)
            HttpResponse(200, ApiSuccessResponse(data = case, correlationId = correlationId), correlationId)
        }

        request.path.startsWith("/api/v1/vendor-portal/reconciliation/") && request.method == "GET" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            val caseId = request.path.substringAfter("/api/v1/vendor-portal/reconciliation/")
            val case = useCases.getVendorPortalReconciliationCaseById(principal, caseId)
            HttpResponse(200, ApiSuccessResponse(data = case, correlationId = correlationId), correlationId)
        }

        (request.path == "/api/v1/vendor-portal/reconciliation" || request.path.startsWith("/api/v1/vendor-portal/reconciliation?")) && request.method == "GET" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            val queryParams = if (request.path.contains("?")) {
                request.path.substringAfter("?").split("&").mapNotNull {
                    val parts = it.split("=")
                    if (parts.size == 2) parts[0] to parts[1] else null
                }.toMap()
            } else emptyMap()
            val settlementId = queryParams["settlementId"]
            val invoiceId = queryParams["invoiceId"]
            val status = queryParams["status"]
            val cases = useCases.listVendorPortalReconciliationCases(principal, settlementId, invoiceId, status)
            HttpResponse(200, ApiSuccessResponse(data = cases, correlationId = correlationId), correlationId)
        }

        request.path == "/api/v1/vendor-portal/reconciliation" && request.method == "POST" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            val reqDto = when (val b = request.body) {
                is VendorPortalReconciliationQueryRequest -> b
                is Map<*, *> -> VendorPortalReconciliationQueryRequest(
                    settlementId = b["settlementId"]?.toString(),
                    invoiceId = b["invoiceId"]?.toString(),
                    subject = b["subject"]?.toString() ?: "",
