            HttpResponse(200, ApiSuccessResponse(data = mapOf("success" to success), correlationId = correlationId), correlationId)
        }

        (request.path == "/api/v1/vendor-portal/notifications" || request.path.startsWith("/api/v1/vendor-portal/notifications?")) && request.method == "GET" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            val queryParams = if (request.path.contains("?")) {
                request.path.substringAfter("?").split("&").mapNotNull {
                    val parts = it.split("=")
                    if (parts.size == 2) parts[0] to parts[1] else null
                }.toMap()
            } else emptyMap()
            val category = queryParams["category"]
            val status = queryParams["status"]
            val limit = queryParams["limit"]?.toIntOrNull() ?: 50
            val offset = queryParams["offset"]?.toIntOrNull() ?: 0
            val notifs = useCases.listVendorPortalNotifications(principal, category, status, limit, offset)
            HttpResponse(200, ApiSuccessResponse(data = notifs, correlationId = correlationId), correlationId)
        }

        request.path == "/api/v1/vendor-portal/notifications" && request.method == "POST" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            val reqDto = when (val b = request.body) {
                is VendorPortalEmitNotificationRequest -> b
                is Map<*, *> -> VendorPortalEmitNotificationRequest(
                    category = b["category"]?.toString() ?: "OPERATIONS",
                    severity = b["severity"]?.toString() ?: "NORMAL",
                    title = b["title"]?.toString() ?: "",
                    message = b["message"]?.toString() ?: "",
                    relatedEntityType = b["relatedEntityType"]?.toString(),
                    relatedEntityId = b["relatedEntityId"]?.toString(),
                    deepLinkTarget = b["deepLinkTarget"]?.toString(),
                    idempotencyKey = b["idempotencyKey"]?.toString()
                )
                else -> throw ValidationException("Request body must be a valid VendorPortalEmitNotificationRequest.")
            }
            val notif = useCases.emitVendorPortalNotification(principal, reqDto)
            HttpResponse(201, ApiSuccessResponse(data = notif, correlationId = correlationId), correlationId)
        }

        // --- Search ---
        (request.path == "/api/v1/vendor-portal/search" || request.path.startsWith("/api/v1/vendor-portal/search?")) && request.method == "GET" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            val queryParams = if (request.path.contains("?")) {
                request.path.substringAfter("?").split("&").mapNotNull {
                    val parts = it.split("=")
                    if (parts.size == 2) parts[0] to parts[1] else null
                }.toMap()
            } else emptyMap()
            val query = queryParams["q"] ?: queryParams["query"] ?: ""
            val typesStr = queryParams["types"] ?: queryParams["type"]
            val types = typesStr?.split(",")?.map { it.trim() } ?: emptyList()
            val page = queryParams["page"]?.toIntOrNull() ?: 1
            val pageSize = queryParams["pageSize"]?.toIntOrNull() ?: 20
            val searchRes = useCases.searchVendorPortal(principal, query, types, page, pageSize)
            HttpResponse(200, ApiSuccessResponse(data = searchRes, correlationId = correlationId), correlationId)
        }

        // --- Activity Timeline ---
        (request.path == "/api/v1/vendor-portal/activity-timeline" || request.path.startsWith("/api/v1/vendor-portal/activity-timeline?")) && request.method == "GET" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            val queryParams = if (request.path.contains("?")) {
                request.path.substringAfter("?").split("&").mapNotNull {
                    val parts = it.split("=")
                    if (parts.size == 2) parts[0] to parts[1] else null
                }.toMap()
            } else emptyMap()
            val page = queryParams["page"]?.toIntOrNull() ?: 1
            val pageSize = queryParams["pageSize"]?.toIntOrNull() ?: 30
            val timeline = useCases.getVendorPortalActivityTimeline(principal, page, pageSize)
            HttpResponse(200, ApiSuccessResponse(data = timeline, correlationId = correlationId), correlationId)
        }

        // --- Unified Workspace Summary ---
        request.path == "/api/v1/vendor-portal/workspace-summary" && request.method == "GET" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            val summary = useCases.getVendorPortalUnifiedWorkspaceSummary(principal)
            HttpResponse(200, ApiSuccessResponse(data = summary, correlationId = correlationId), correlationId)
        }


        // ==========================================
        // MODULE 17 STEP 02 - PRINTING QUOTATION
        // ==========================================

        request.path == "/api/v1/printing-quotes" && request.method == "POST" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            val reqDto = parseCreatePrintingQuoteRequest(request.body)
            val res = useCases.createPrintingQuote(principal, reqDto)
            HttpResponse(201, ApiSuccessResponse(data = res, correlationId = correlationId), correlationId)
        }

        request.path == "/api/v1/printing-quotes/calculate" && request.method == "POST" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            val reqDto = parseCalculatePrintingQuoteRequest(request.body)
            val res = useCases.calculatePrintingQuote(principal, reqDto)
            HttpResponse(200, ApiSuccessResponse(data = res, correlationId = correlationId), correlationId)
        }

        request.path == "/api/v1/printing-quotes/recalculate" && request.method == "POST" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            val reqDto = parseCalculatePrintingQuoteRequest(request.body)
            val res = useCases.recalculatePrintingQuote(principal, reqDto)
            HttpResponse(200, ApiSuccessResponse(data = res, correlationId = correlationId), correlationId)
        }

        request.path == "/api/v1/printing-quotes/review" && request.method == "POST" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            val reqDto = parseQuoteReviewRequest(request.body)
            val res = useCases.reviewPrintingQuote(principal, reqDto)
            HttpResponse(200, ApiSuccessResponse(data = res, correlationId = correlationId), correlationId)
        }

        request.path.matches(Regex("^/api/v1/printing-quotes/[^/]+/submit-review$")) && request.method == "POST" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            val id = request.path.removePrefix("/api/v1/printing-quotes/").removeSuffix("/submit-review")
            val res = useCases.submitPrintingQuoteForReview(principal, id)
            HttpResponse(200, ApiSuccessResponse(data = res, correlationId = correlationId), correlationId)
        }

        request.path.matches(Regex("^/api/v1/printing-quotes/[^/]+/reconcile$")) && request.method == "POST" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            val queryParams = parseQueryParams(request.path)
            val id = request.path.removePrefix("/api/v1/printing-quotes/").substringBefore("?").removeSuffix("/reconcile")
            val versionId = queryParams["versionId"] ?: (request.body as? Map<String, Any?>)?.get("versionId")?.toString() ?: ""
            val res = useCases.reconcilePrintingQuote(principal, id, versionId)
            HttpResponse(200, ApiSuccessResponse(data = res, correlationId = correlationId), correlationId)
        }

        request.path.matches(Regex("^/api/v1/printing-quotes/[^/]+/breakdown$")) && request.method == "GET" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            val versionId = request.path.removePrefix("/api/v1/printing-quotes/").removeSuffix("/breakdown")
            val res = useCases.getPrintingQuoteCostBreakdown(principal, versionId)
            HttpResponse(200, ApiSuccessResponse(data = res, correlationId = correlationId), correlationId)
        }

        request.path.matches(Regex("^/api/v1/printing-quotes/[^/]+/tiers$")) && request.method == "GET" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            val versionId = request.path.removePrefix("/api/v1/printing-quotes/").removeSuffix("/tiers")
            val res = useCases.getPrintingQuoteQuantityTiers(principal, versionId)
            HttpResponse(200, ApiSuccessResponse(data = res, correlationId = correlationId), correlationId)
        }

        request.path.matches(Regex("^/api/v1/printing-quotes/[^/]+/audit$")) && request.method == "GET" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            val id = request.path.removePrefix("/api/v1/printing-quotes/").removeSuffix("/audit")
            val res = useCases.getPrintingQuoteAuditTrail(principal, id)
            HttpResponse(200, ApiSuccessResponse(data = res, correlationId = correlationId), correlationId)
        }

        request.path.matches(Regex("^/api/v1/printing-quotes/[^/]+/handoff$")) && request.method == "GET" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            val id = request.path.removePrefix("/api/v1/printing-quotes/").removeSuffix("/handoff")
            val res = useCases.exportPrintingQuoteHandoffContract(principal, id)
            HttpResponse(200, ApiSuccessResponse(data = res, correlationId = correlationId), correlationId)
        }

        request.path.matches(Regex("^/api/v1/printing-quotes/[^/]+/versions$")) && request.method == "GET" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            val id = request.path.removePrefix("/api/v1/printing-quotes/").removeSuffix("/versions")
            val res = useCases.listPrintingQuoteVersions(principal, id)
            HttpResponse(200, ApiSuccessResponse(data = res, correlationId = correlationId), correlationId)
        }

        request.path.matches(Regex("^/api/v1/printing-quotes/versions/[^/]+$")) && request.method == "GET" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            val versionId = request.path.removePrefix("/api/v1/printing-quotes/versions/")
            val res = useCases.getPrintingQuoteVersion(principal, versionId)
            HttpResponse(200, ApiSuccessResponse(data = res, correlationId = correlationId), correlationId)
        }

        request.path.matches(Regex("^/api/v1/printing-quotes/[^/]+$")) && request.method == "GET" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            val id = request.path.removePrefix("/api/v1/printing-quotes/")
            val res = useCases.getPrintingQuote(principal, id)
            HttpResponse(200, ApiSuccessResponse(data = res, correlationId = correlationId), correlationId)
        }

        else -> null
    }

    // =========================================================================
    // 23. VENDOR PORTAL WORKFLOW ORCHESTRATION & CROSS-MODULE INTEGRATION (Module 13 Step 11)
    // =========================================================================
    private suspend fun handleVendorPortalWorkflowRoutes(request: HttpRequest, correlationId: String): HttpResponse? = when {
        // --- Hub Summary ---
        request.path == "/api/v1/vendor-portal/workflows/hub-summary" && request.method == "GET" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            val summary = useCases.getVendorWorkflowHubSummary(principal)
            HttpResponse(200, ApiSuccessResponse(data = summary, correlationId = correlationId), correlationId)
        }

        // --- List Workflows ---
        (request.path == "/api/v1/vendor-portal/workflows" || request.path.startsWith("/api/v1/vendor-portal/workflows?")) && request.method == "GET" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            val queryParams = if (request.path.contains("?")) {
                request.path.substringAfter("?").split("&").mapNotNull {
                    val parts = it.split("=")
                    if (parts.size == 2) parts[0] to parts[1] else null
                }.toMap()
            } else emptyMap()
            val status = queryParams["status"]
            val stage = queryParams["stage"]
            val limit = queryParams["limit"]?.toIntOrNull() ?: 50
            val offset = queryParams["offset"]?.toIntOrNull() ?: 0
            val list = useCases.listVendorWorkflows(principal, status, stage, limit, offset)
            HttpResponse(200, ApiSuccessResponse(data = list, correlationId = correlationId), correlationId)
        }

        // --- Sync Workflow from Module 12 ---
        request.path == "/api/v1/vendor-portal/workflows/sync" && request.method == "POST" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            val reqDto = when (val b = request.body) {
                is VendorWorkflowSyncRequest -> b
                is Map<*, *> -> VendorWorkflowSyncRequest(
                    correlationId = b["correlationId"]?.toString() ?: throw ValidationException("Missing correlationId")
                )
                else -> throw ValidationException("Request body must be a valid VendorWorkflowSyncRequest.")
            }
            val synced = useCases.syncVendorWorkflow(principal, reqDto)
            HttpResponse(200, ApiSuccessResponse(data = synced, correlationId = correlationId), correlationId)
        }

        // --- Workflow Timeline ---
        request.path.startsWith("/api/v1/vendor-portal/workflows/") && request.path.endsWith("/timeline") && request.method == "GET" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            val workflowId = request.path.substringAfter("/api/v1/vendor-portal/workflows/").substringBefore("/timeline")
            val timeline = useCases.getVendorWorkflowTimeline(principal, workflowId)
            HttpResponse(200, ApiSuccessResponse(data = timeline, correlationId = correlationId), correlationId)
        }

        // --- Workflow SLA Projection ---
        request.path.startsWith("/api/v1/vendor-portal/workflows/") && request.path.endsWith("/sla") && request.method == "GET" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            val workflowId = request.path.substringAfter("/api/v1/vendor-portal/workflows/").substringBefore("/sla")
            val sla = useCases.getVendorWorkflowSlaProjection(principal, workflowId)
            HttpResponse(200, ApiSuccessResponse(data = sla, correlationId = correlationId), correlationId)
        }

        // --- Workflow Exceptions List ---
        (request.path.startsWith("/api/v1/vendor-portal/workflows/") && request.path.contains("/exceptions") && !request.path.contains("/resolve")) && request.method == "GET" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            val workflowId = request.path.substringAfter("/api/v1/vendor-portal/workflows/").substringBefore("/exceptions")
            val exceptions = useCases.getVendorWorkflowExceptions(principal, workflowId.takeIf { it != "all" })
            HttpResponse(200, ApiSuccessResponse(data = exceptions, correlationId = correlationId), correlationId)
        }

        // --- Record Workflow Exception ---
        request.path.startsWith("/api/v1/vendor-portal/workflows/") && request.path.endsWith("/exceptions") && request.method == "POST" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            val workflowId = request.path.substringAfter("/api/v1/vendor-portal/workflows/").substringBefore("/exceptions")
            val reqDto = when (val b = request.body) {
                is VendorWorkflowRecordExceptionRequest -> b
                is Map<*, *> -> VendorWorkflowRecordExceptionRequest(
                    category = b["category"]?.toString() ?: throw ValidationException("Missing category"),
                    severity = b["severity"]?.toString() ?: "MEDIUM",
                    title = b["title"]?.toString() ?: throw ValidationException("Missing title"),
                    description = b["description"]?.toString() ?: throw ValidationException("Missing description")
                )
                else -> throw ValidationException("Request body must be a valid VendorWorkflowRecordExceptionRequest.")
            }
            val created = useCases.recordVendorWorkflowException(principal, workflowId, reqDto)
            HttpResponse(201, ApiSuccessResponse(data = created, correlationId = correlationId), correlationId)
        }

        // --- Resolve Workflow Exception ---
        request.path.startsWith("/api/v1/vendor-portal/workflows/exceptions/") && request.path.endsWith("/resolve") && request.method == "POST" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            val exceptionId = request.path.substringAfter("/api/v1/vendor-portal/workflows/exceptions/").substringBefore("/resolve")
            val reqDto = when (val b = request.body) {
                is VendorWorkflowResolveExceptionRequest -> b
                is Map<*, *> -> VendorWorkflowResolveExceptionRequest(
                    resolutionNotes = b["resolutionNotes"]?.toString() ?: throw ValidationException("Missing resolutionNotes")
                )
                else -> throw ValidationException("Request body must be a valid VendorWorkflowResolveExceptionRequest.")
            }
            val resolved = useCases.resolveVendorWorkflowException(principal, exceptionId, reqDto)
            HttpResponse(200, ApiSuccessResponse(data = resolved, correlationId = correlationId), correlationId)
        }

        // --- Workflow Next Actions List ---
        (request.path.startsWith("/api/v1/vendor-portal/workflows/") && request.path.endsWith("/actions")) && request.method == "GET" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            val workflowId = request.path.substringAfter("/api/v1/vendor-portal/workflows/").substringBefore("/actions")
            val actions = useCases.getVendorWorkflowNextActions(principal, workflowId.takeIf { it != "all" })
            HttpResponse(200, ApiSuccessResponse(data = actions, correlationId = correlationId), correlationId)
        }

        // --- Acknowledge Workflow Action ---
        request.path.startsWith("/api/v1/vendor-portal/workflows/") && request.path.contains("/actions/") && request.path.endsWith("/acknowledge") && request.method == "POST" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            val workflowId = request.path.substringAfter("/api/v1/vendor-portal/workflows/").substringBefore("/actions/")
            val actionId = request.path.substringAfter("/actions/").substringBefore("/acknowledge")
            val completed = useCases.acknowledgeVendorWorkflowAction(principal, workflowId, actionId)
            HttpResponse(200, ApiSuccessResponse(data = completed, correlationId = correlationId), correlationId)
        }

        // --- Single Workflow Details ---
        request.path.startsWith("/api/v1/vendor-portal/workflows/") && request.method == "GET" && !request.path.contains("/") -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            val workflowId = request.path.substringAfter("/api/v1/vendor-portal/workflows/")
            val details = useCases.getVendorWorkflowDetails(principal, workflowId)
            HttpResponse(200, ApiSuccessResponse(data = details, correlationId = correlationId), correlationId)
        }

        // =========================================================================
        // MODULE 14 STEP 01: CUSTOMER FINANCIAL ACCOUNT ENDPOINTS
        // =========================================================================

        // --- Create Customer Financial Account ---
        request.path == "/api/v1/customer-financial-accounts" && request.method == "POST" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            val reqDto = when (val b = request.body) {
                is CreateCustomerFinancialAccountRequest -> b
                is Map<*, *> -> CreateCustomerFinancialAccountRequest(
                    customerId = b["customerId"]?.toString() ?: throw ValidationException("Missing customerId"),
                    currency = b["currency"]?.toString() ?: "BDT",
                    notes = b["notes"]?.toString()
                )
                is String -> {
                    val map = com.sucharu.sucharupro.data.event.serialization.EventSerializationHelper.parseJsonObject(b)
                    CreateCustomerFinancialAccountRequest(
                        customerId = map["customerId"] ?: throw ValidationException("Missing customerId"),
                        currency = map["currency"] ?: "BDT",
                        notes = map["notes"]
                    )
                }
                else -> throw ValidationException("Request body must be a valid CreateCustomerFinancialAccountRequest.")
            }
            val account = useCases.createCustomerFinancialAccount(principal, reqDto)
            HttpResponse(201, ApiSuccessResponse(data = account, correlationId = correlationId), correlationId)
        }

        // --- List Customer Financial Accounts ---
        (request.path == "/api/v1/customer-financial-accounts" || request.path.startsWith("/api/v1/customer-financial-accounts?")) && request.method == "GET" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            val queryParams = if (request.path.contains("?")) {
                request.path.substringAfter("?").split("&").mapNotNull {
                    val parts = it.split("=")
                    if (parts.size == 2) parts[0] to parts[1] else null
                }.toMap()
            } else emptyMap()
            val status = queryParams["status"]
            val limit = queryParams["limit"]?.toIntOrNull() ?: 50
            val offset = queryParams["offset"]?.toIntOrNull() ?: 0
            val list = useCases.listCustomerFinancialAccounts(principal, status, limit, offset)
            HttpResponse(200, ApiSuccessResponse(data = list, correlationId = correlationId), correlationId)
        }

        // --- Get Customer Financial Account by Customer ID ---
        request.path.startsWith("/api/v1/customers/") && request.path.endsWith("/financial-account") && request.method == "GET" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            val customerId = request.path.substringAfter("/api/v1/customers/").substringBefore("/financial-account")
            val account = useCases.getCustomerFinancialAccountByCustomer(principal, customerId)
            HttpResponse(200, ApiSuccessResponse(data = account, correlationId = correlationId), correlationId)
        }

        // --- Update Customer Financial Account Status ---
        request.path.startsWith("/api/v1/customer-financial-accounts/") && request.path.endsWith("/status") && request.method == "POST" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            val accountId = request.path.substringAfter("/api/v1/customer-financial-accounts/").substringBefore("/status")
            val reqDto = when (val b = request.body) {
                is UpdateCustomerFinancialAccountStatusRequest -> b
                is Map<*, *> -> UpdateCustomerFinancialAccountStatusRequest(
                    status = b["status"]?.toString() ?: throw ValidationException("Missing status"),
                    reason = b["reason"]?.toString(),
                    expectedVersion = b["expectedVersion"]?.toString()?.toLongOrNull() ?: 1L
                )
                is String -> {
                    val map = com.sucharu.sucharupro.data.event.serialization.EventSerializationHelper.parseJsonObject(b)
                    UpdateCustomerFinancialAccountStatusRequest(
                        status = map["status"] ?: throw ValidationException("Missing status"),
                        reason = map["reason"],
                        expectedVersion = map["expectedVersion"]?.toLongOrNull() ?: 1L
                    )
                }
                else -> throw ValidationException("Request body must be a valid UpdateCustomerFinancialAccountStatusRequest.")
            }
            val updated = useCases.updateCustomerFinancialAccountStatus(principal, accountId, reqDto)
            HttpResponse(200, ApiSuccessResponse(data = updated, correlationId = correlationId), correlationId)
        }

        // --- Update Customer Financial Account Notes ---
        request.path.startsWith("/api/v1/customer-financial-accounts/") && request.path.endsWith("/notes") && request.method == "POST" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            val accountId = request.path.substringAfter("/api/v1/customer-financial-accounts/").substringBefore("/notes")
            val reqDto = when (val b = request.body) {
                is UpdateCustomerFinancialAccountNotesRequest -> b
                is Map<*, *> -> UpdateCustomerFinancialAccountNotesRequest(
                    notes = b["notes"]?.toString(),
                    expectedVersion = b["expectedVersion"]?.toString()?.toLongOrNull() ?: 1L
                )
                is String -> {
                    val map = com.sucharu.sucharupro.data.event.serialization.EventSerializationHelper.parseJsonObject(b)
                    UpdateCustomerFinancialAccountNotesRequest(
                        notes = map["notes"],
                        expectedVersion = map["expectedVersion"]?.toLongOrNull() ?: 1L
                    )
                }
                else -> throw ValidationException("Request body must be a valid UpdateCustomerFinancialAccountNotesRequest.")
            }
            val updated = useCases.updateCustomerFinancialAccountNotes(principal, accountId, reqDto)
            HttpResponse(200, ApiSuccessResponse(data = updated, correlationId = correlationId), correlationId)
        }

        // --- Get Customer Financial Account Audit History ---
        request.path.startsWith("/api/v1/customer-financial-accounts/") && request.path.endsWith("/audit") && request.method == "GET" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            val accountId = request.path.substringAfter("/api/v1/customer-financial-accounts/").substringBefore("/audit")
            val auditList = useCases.getCustomerFinancialAccountAuditHistory(principal, accountId)
            HttpResponse(200, ApiSuccessResponse(data = auditList, correlationId = correlationId), correlationId)
        }

        // --- Get Customer Financial Account by Financial Account ID ---
        request.path.startsWith("/api/v1/customer-financial-accounts/") && request.method == "GET" && !request.path.substringAfter("/api/v1/customer-financial-accounts/").contains("/") -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            val accountId = request.path.substringAfter("/api/v1/customer-financial-accounts/")
            val account = useCases.getCustomerFinancialAccount(principal, accountId)
            HttpResponse(200, ApiSuccessResponse(data = account, correlationId = correlationId), correlationId)
        }

        // =========================================================================
        // MODULE 14 STEP 02: CUSTOMER INVOICE & RECEIVABLE FOUNDATION ENDPOINTS
        // =========================================================================

        // --- Create Customer Invoice Draft ---
        request.path == "/api/v1/customer-invoices" && request.method == "POST" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            val reqDto = when (val b = request.body) {
                is CreateCustomerInvoiceRequest -> b
                is Map<*, *> -> CreateCustomerInvoiceRequest(
                    customerId = b["customerId"]?.toString() ?: throw ValidationException("Missing customerId"),
                    customerFinancialAccountId = b["customerFinancialAccountId"]?.toString() ?: throw ValidationException("Missing customerFinancialAccountId"),
                    sourceOrderId = b["sourceOrderId"]?.toString(),
                    sourceJobId = b["sourceJobId"]?.toString(),
                    dueDate = b["dueDate"]?.toString()?.toLongOrNull(),
                    currency = b["currency"]?.toString() ?: "BDT",
                    discount = b["discount"]?.toString()?.let { java.math.BigDecimal(it) } ?: java.math.BigDecimal.ZERO,
                    tax = b["tax"]?.toString()?.let { java.math.BigDecimal(it) } ?: java.math.BigDecimal.ZERO,
                    adjustment = b["adjustment"]?.toString()?.let { java.math.BigDecimal(it) } ?: java.math.BigDecimal.ZERO,
                    notes = b["notes"]?.toString()
                )
                else -> throw ValidationException("Request body must be a valid CreateCustomerInvoiceRequest.")
            }
            val invoice = useCases.createCustomerInvoice(principal, reqDto)
            HttpResponse(201, ApiSuccessResponse(data = invoice, correlationId = correlationId), correlationId)
        }

        // --- List Customer Invoices ---
        (request.path == "/api/v1/customer-invoices" || request.path.startsWith("/api/v1/customer-invoices?")) && request.method == "GET" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            val queryParams = if (request.path.contains("?")) {
                request.path.substringAfter("?").split("&").mapNotNull {
                    val parts = it.split("=")
                    if (parts.size == 2) parts[0] to parts[1] else null
                }.toMap()
            } else emptyMap()
