            HttpResponse(200, ApiSuccessResponse(data = resAlert, correlationId = correlationId), correlationId)
        }

        // --- Dismiss Customer Financial Alert ---
        request.path.startsWith("/api/v1/customer-financial-alerts/") && request.path.endsWith("/dismiss") && request.method == "POST" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            val alertId = request.path.substringAfter("/api/v1/customer-financial-alerts/").substringBefore("/dismiss")
            val reqDto = when (val b = request.body) {
                is DismissCustomerFinancialAlertRequest -> b
                is Map<*, *> -> DismissCustomerFinancialAlertRequest(
                    reason = b["reason"]?.toString() ?: throw ValidationException("Missing dismissal reason")
                )
                else -> throw ValidationException("Request body must be a valid DismissCustomerFinancialAlertRequest.")
            }
            val disAlert = useCases.dismissCustomerFinancialAlert(principal, alertId, reqDto)
            HttpResponse(200, ApiSuccessResponse(data = disAlert, correlationId = correlationId), correlationId)
        }

        // --- Get Customer Financial Alert Audit Trail ---
        request.path.startsWith("/api/v1/customer-financial-alerts/") && request.path.endsWith("/audit") && request.method == "GET" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            val alertId = request.path.substringAfter("/api/v1/customer-financial-alerts/").substringBefore("/audit")
            val audits = useCases.getCustomerFinancialAlertAuditHistory(principal, alertId)
            HttpResponse(200, ApiSuccessResponse(data = audits, correlationId = correlationId), correlationId)
        }

        // --- Get Single Customer Financial Alert ---
        request.path.startsWith("/api/v1/customer-financial-alerts/") && request.method == "GET" && !request.path.contains("/audit") -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            val alertId = request.path.substringAfter("/api/v1/customer-financial-alerts/")
            val alert = useCases.getCustomerFinancialAlert(principal, alertId)
            HttpResponse(200, ApiSuccessResponse(data = alert, correlationId = correlationId), correlationId)
        }

        // --- Create Customer Financial Report Schedule ---
        request.path.startsWith("/api/v1/customers/") && request.path.endsWith("/financial-report-schedules") && request.method == "POST" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            val customerId = request.path.substringAfter("/api/v1/customers/").substringBefore("/financial-report-schedules")
            val reqDto = when (val b = request.body) {
                is CreateCustomerFinancialReportScheduleRequest -> b
                is Map<*, *> -> CreateCustomerFinancialReportScheduleRequest(
                    reportType = b["reportType"]?.toString() ?: throw ValidationException("Missing reportType"),
                    format = b["format"]?.toString() ?: "PDF",
                    frequency = b["frequency"]?.toString() ?: throw ValidationException("Missing frequency"),
                    timezone = b["timezone"]?.toString() ?: "Asia/Dhaka",
                    firstRunAt = (b["firstRunAt"] as? Number)?.toLong()
                )
                else -> throw ValidationException("Request body must be a valid CreateCustomerFinancialReportScheduleRequest.")
            }
            val created = useCases.createCustomerFinancialReportSchedule(principal, customerId, reqDto)
            HttpResponse(201, ApiSuccessResponse(data = created, correlationId = correlationId), correlationId)
        }

        // --- List Customer-Specific Financial Report Schedules ---
        (request.path.startsWith("/api/v1/customers/") && (request.path.endsWith("/financial-report-schedules") || request.path.contains("/financial-report-schedules?"))) && request.method == "GET" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            val customerId = request.path.substringAfter("/api/v1/customers/").substringBefore("/financial-report-schedules")
            val queryParams = if (request.path.contains("?")) {
                request.path.substringAfter("?").split("&").mapNotNull {
                    val parts = it.split("=")
                    if (parts.size == 2) parts[0] to parts[1] else null
                }.toMap()
            } else emptyMap()
            val status = queryParams["status"]
            val list = useCases.listCustomerFinancialReportSchedules(principal, customerId, status)
            HttpResponse(200, ApiSuccessResponse(data = list, correlationId = correlationId), correlationId)
        }

        // --- List All Financial Report Schedules ---
        (request.path == "/api/v1/customer-financial-report-schedules" || request.path.startsWith("/api/v1/customer-financial-report-schedules?")) && request.method == "GET" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            val queryParams = if (request.path.contains("?")) {
                request.path.substringAfter("?").split("&").mapNotNull {
                    val parts = it.split("=")
                    if (parts.size == 2) parts[0] to parts[1] else null
                }.toMap()
            } else emptyMap()
            val customerId = queryParams["customerId"]
            val status = queryParams["status"]
            val list = useCases.listCustomerFinancialReportSchedules(principal, customerId, status)
            HttpResponse(200, ApiSuccessResponse(data = list, correlationId = correlationId), correlationId)
        }

        // --- Update Customer Financial Report Schedule ---
        request.path.startsWith("/api/v1/customer-financial-report-schedules/") && request.method == "PUT" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            val scheduleId = request.path.substringAfter("/api/v1/customer-financial-report-schedules/")
            val reqDto = when (val b = request.body) {
                is UpdateCustomerFinancialReportScheduleRequest -> b
                is Map<*, *> -> UpdateCustomerFinancialReportScheduleRequest(
                    format = b["format"]?.toString(),
                    frequency = b["frequency"]?.toString(),
                    timezone = b["timezone"]?.toString(),
                    nextRunAt = (b["nextRunAt"] as? Number)?.toLong()
                )
                else -> throw ValidationException("Request body must be a valid UpdateCustomerFinancialReportScheduleRequest.")
            }
            val updated = useCases.updateCustomerFinancialReportSchedule(principal, scheduleId, reqDto)
            HttpResponse(200, ApiSuccessResponse(data = updated, correlationId = correlationId), correlationId)
        }

        // --- Pause Schedule ---
        request.path.startsWith("/api/v1/customer-financial-report-schedules/") && request.path.endsWith("/pause") && request.method == "POST" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            val scheduleId = request.path.substringAfter("/api/v1/customer-financial-report-schedules/").substringBefore("/pause")
            val paused = useCases.pauseCustomerFinancialReportSchedule(principal, scheduleId)
            HttpResponse(200, ApiSuccessResponse(data = paused, correlationId = correlationId), correlationId)
        }

        // --- Resume Schedule ---
        request.path.startsWith("/api/v1/customer-financial-report-schedules/") && request.path.endsWith("/resume") && request.method == "POST" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            val scheduleId = request.path.substringAfter("/api/v1/customer-financial-report-schedules/").substringBefore("/resume")
            val resumed = useCases.resumeCustomerFinancialReportSchedule(principal, scheduleId)
            HttpResponse(200, ApiSuccessResponse(data = resumed, correlationId = correlationId), correlationId)
        }

        // --- Cancel Schedule ---
        request.path.startsWith("/api/v1/customer-financial-report-schedules/") && request.path.endsWith("/cancel") && request.method == "POST" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            val scheduleId = request.path.substringAfter("/api/v1/customer-financial-report-schedules/").substringBefore("/cancel")
            val cancelled = useCases.cancelCustomerFinancialReportSchedule(principal, scheduleId)
            HttpResponse(200, ApiSuccessResponse(data = cancelled, correlationId = correlationId), correlationId)
        }

        // --- List Schedule Executions ---
        (request.path.startsWith("/api/v1/customer-financial-report-schedules/") && (request.path.endsWith("/executions") || request.path.contains("/executions?"))) && request.method == "GET" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            val scheduleId = request.path.substringAfter("/api/v1/customer-financial-report-schedules/").substringBefore("/executions")
            val queryParams = if (request.path.contains("?")) {
                request.path.substringAfter("?").split("&").mapNotNull {
                    val parts = it.split("=")
                    if (parts.size == 2) parts[0] to parts[1] else null
                }.toMap()
            } else emptyMap()
            val limit = queryParams["limit"]?.toIntOrNull() ?: 50
            val executions = useCases.listCustomerFinancialScheduleExecutions(principal, scheduleId, limit)
            HttpResponse(200, ApiSuccessResponse(data = executions, correlationId = correlationId), correlationId)
        }

        else -> {
            handleBusinessExpenseRoutes(request, correlationId)
                ?: handleVendorPayableRoutes(request, correlationId)
                ?: handleBusinessLedgerRoutes(request, correlationId)
                ?: handleProfitabilityAnalysisRoutes(request, correlationId)
                ?: handleVendorProfitabilityRoutes(request, correlationId)
        }
    }

    // =========================================================================
    // MODULE 15 STEP 01: BUSINESS EXPENSE REST ROUTES
    // =========================================================================

    private suspend fun handleBusinessExpenseRoutes(request: HttpRequest, correlationId: String): HttpResponse? = when {
        // --- Create Business Expense ---
        request.path == "/api/v1/business-expenses" && request.method == "POST" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            val reqDto = when (val b = request.body) {
                is CreateBusinessExpenseRequest -> b
                is Map<*, *> -> CreateBusinessExpenseRequest(
                    categoryId = b["categoryId"]?.toString() ?: throw ValidationException("Missing categoryId"),
                    amount = b["amount"]?.toString() ?: throw ValidationException("Missing amount"),
                    currency = b["currency"]?.toString() ?: "BDT",
                    expenseDate = (b["expenseDate"] as? Number)?.toLong(),
                    paymentMethod = b["paymentMethod"]?.toString() ?: "CASH",
                    paymentReference = b["paymentReference"]?.toString(),
                    vendorId = b["vendorId"]?.toString(),
                    jobId = b["jobId"]?.toString(),
                    branchId = b["branchId"]?.toString(),
                    locationId = b["locationId"]?.toString(),
                    description = b["description"]?.toString() ?: throw ValidationException("Missing description"),
                    notes = b["notes"]?.toString(),
                    attachmentUrl = b["attachmentUrl"]?.toString(),
                    attachmentMetadata = b["attachmentMetadata"]?.toString(),
                    autoSubmit = b["autoSubmit"] as? Boolean ?: false
                )
                else -> throw ValidationException("Request body must be a valid CreateBusinessExpenseRequest.")
            }
            val created = useCases.createBusinessExpense(principal, reqDto, request.idempotencyKey)
            HttpResponse(201, ApiSuccessResponse(data = created, correlationId = correlationId), correlationId)
        }

        // --- List Business Expenses ---
        (request.path == "/api/v1/business-expenses" || request.path.startsWith("/api/v1/business-expenses?")) && request.method == "GET" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            val queryParams = if (request.path.contains("?")) {
                request.path.substringAfter("?").split("&").mapNotNull {
                    val parts = it.split("=")
                    if (parts.size == 2) parts[0] to parts[1] else null
                }.toMap()
            } else emptyMap()

            val status = queryParams["status"]
            val categoryId = queryParams["categoryId"]
            val vendorId = queryParams["vendorId"]
            val jobId = queryParams["jobId"]
            val fromDate = queryParams["fromDate"]?.toLongOrNull()
            val toDate = queryParams["toDate"]?.toLongOrNull()
            val limit = queryParams["limit"]?.toIntOrNull() ?: 50
            val offset = queryParams["offset"]?.toIntOrNull() ?: 0

            val list = useCases.listBusinessExpenses(
                principal = principal,
                status = status,
                categoryId = categoryId,
                vendorId = vendorId,
                jobId = jobId,
                fromDate = fromDate,
                toDate = toDate,
                limit = limit,
                offset = offset
            )
            HttpResponse(200, ApiSuccessResponse(data = list, correlationId = correlationId), correlationId)
        }

        // --- Get Business Expense by ID ---
        request.path.startsWith("/api/v1/business-expenses/") && !request.path.contains("/submit") && !request.path.contains("/approve") && !request.path.contains("/reject") && !request.path.contains("/cancel") && !request.path.contains("/audit") && request.method == "GET" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            val expenseId = request.path.substringAfter("/api/v1/business-expenses/").substringBefore("?")
            val expense = useCases.getBusinessExpense(principal, expenseId)
            HttpResponse(200, ApiSuccessResponse(data = expense, correlationId = correlationId), correlationId)
        }

        // --- Update Draft Business Expense ---
        request.path.startsWith("/api/v1/business-expenses/") && !request.path.contains("/submit") && !request.path.contains("/approve") && !request.path.contains("/reject") && !request.path.contains("/cancel") && !request.path.contains("/audit") && request.method == "PUT" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            val expenseId = request.path.substringAfter("/api/v1/business-expenses/").substringBefore("?")
            val reqDto = when (val b = request.body) {
                is UpdateBusinessExpenseRequest -> b
                is Map<*, *> -> UpdateBusinessExpenseRequest(
                    categoryId = b["categoryId"]?.toString(),
                    amount = b["amount"]?.toString(),
                    currency = b["currency"]?.toString(),
                    expenseDate = (b["expenseDate"] as? Number)?.toLong(),
                    paymentMethod = b["paymentMethod"]?.toString(),
                    paymentReference = b["paymentReference"]?.toString(),
                    vendorId = b["vendorId"]?.toString(),
                    jobId = b["jobId"]?.toString(),
                    branchId = b["branchId"]?.toString(),
                    locationId = b["locationId"]?.toString(),
                    description = b["description"]?.toString(),
                    notes = b["notes"]?.toString(),
                    attachmentUrl = b["attachmentUrl"]?.toString(),
                    attachmentMetadata = b["attachmentMetadata"]?.toString()
                )
                else -> throw ValidationException("Request body must be a valid UpdateBusinessExpenseRequest.")
            }
            val updated = useCases.updateBusinessExpense(principal, expenseId, reqDto)
            HttpResponse(200, ApiSuccessResponse(data = updated, correlationId = correlationId), correlationId)
        }

        // --- Submit Business Expense ---
        request.path.startsWith("/api/v1/business-expenses/") && request.path.endsWith("/submit") && request.method == "POST" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            val expenseId = request.path.substringAfter("/api/v1/business-expenses/").substringBefore("/submit")
            val submitted = useCases.submitBusinessExpense(principal, expenseId)
            HttpResponse(200, ApiSuccessResponse(data = submitted, correlationId = correlationId), correlationId)
        }

        // --- Approve Business Expense ---
        request.path.startsWith("/api/v1/business-expenses/") && request.path.endsWith("/approve") && request.method == "POST" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            val expenseId = request.path.substringAfter("/api/v1/business-expenses/").substringBefore("/approve")
            val reqDto = when (val b = request.body) {
                is ApproveExpenseRequest -> b
                is Map<*, *> -> ApproveExpenseRequest(
                    notes = b["notes"]?.toString()
                )
                null -> null
                else -> throw ValidationException("Request body must be a valid ApproveExpenseRequest.")
            }
            val approved = useCases.approveBusinessExpense(principal, expenseId, reqDto)
            HttpResponse(200, ApiSuccessResponse(data = approved, correlationId = correlationId), correlationId)
        }

        // --- Reject Business Expense ---
        request.path.startsWith("/api/v1/business-expenses/") && request.path.endsWith("/reject") && request.method == "POST" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            val expenseId = request.path.substringAfter("/api/v1/business-expenses/").substringBefore("/reject")
            val reqDto = when (val b = request.body) {
                is RejectExpenseRequest -> b
                is Map<*, *> -> RejectExpenseRequest(
                    reason = b["reason"]?.toString() ?: throw ValidationException("Missing rejection reason")
                )
                else -> throw ValidationException("Request body must be a valid RejectExpenseRequest.")
            }
            val rejected = useCases.rejectBusinessExpense(principal, expenseId, reqDto)
            HttpResponse(200, ApiSuccessResponse(data = rejected, correlationId = correlationId), correlationId)
        }

        // --- Cancel Business Expense ---
        request.path.startsWith("/api/v1/business-expenses/") && request.path.endsWith("/cancel") && request.method == "POST" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            val expenseId = request.path.substringAfter("/api/v1/business-expenses/").substringBefore("/cancel")
            val reqDto = when (val b = request.body) {
                is CancelExpenseRequest -> b
                is Map<*, *> -> CancelExpenseRequest(
                    reason = b["reason"]?.toString() ?: throw ValidationException("Missing cancellation reason")
                )
                else -> throw ValidationException("Request body must be a valid CancelExpenseRequest.")
            }
            val cancelled = useCases.cancelBusinessExpense(principal, expenseId, reqDto)
            HttpResponse(200, ApiSuccessResponse(data = cancelled, correlationId = correlationId), correlationId)
        }

        // --- Business Expense Audit Trail ---
        request.path.startsWith("/api/v1/business-expenses/") && request.path.endsWith("/audit") && request.method == "GET" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            val expenseId = request.path.substringAfter("/api/v1/business-expenses/").substringBefore("/audit")
            val audits = useCases.getBusinessExpenseAuditTrail(principal, expenseId)
            HttpResponse(200, ApiSuccessResponse(data = audits, correlationId = correlationId), correlationId)
        }

        // --- List Expense Categories ---
        request.path == "/api/v1/expense-categories" && request.method == "GET" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            val queryParams = if (request.path.contains("?")) {
                request.path.substringAfter("?").split("&").mapNotNull {
                    val parts = it.split("=")
                    if (parts.size == 2) parts[0] to parts[1] else null
                }.toMap()
            } else emptyMap()
            val activeOnly = queryParams["activeOnly"]?.toBooleanStrictOrNull() ?: true
            val categories = useCases.listExpenseCategories(principal, activeOnly)
            HttpResponse(200, ApiSuccessResponse(data = categories, correlationId = correlationId), correlationId)
        }

        // --- Create Expense Category ---
        request.path == "/api/v1/expense-categories" && request.method == "POST" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            val reqDto = when (val b = request.body) {
                is CreateBusinessExpenseCategoryRequest -> b
                is Map<*, *> -> CreateBusinessExpenseCategoryRequest(
                    name = b["name"]?.toString() ?: throw ValidationException("Missing category name"),
                    code = b["code"]?.toString() ?: throw ValidationException("Missing category code"),
                    description = b["description"]?.toString(),
                    sortOrder = (b["sortOrder"] as? Number)?.toInt() ?: 0
                )
                else -> throw ValidationException("Request body must be a valid CreateBusinessExpenseCategoryRequest.")
            }
            val created = useCases.createExpenseCategory(principal, reqDto)
            HttpResponse(201, ApiSuccessResponse(data = created, correlationId = correlationId), correlationId)
        }


        // ==========================================
        // MODULE 17 STEP 02 - PRINTING QUOTATION
        // ==========================================

        request.path == "/api/v1/printing-quotes" && request.method == "POST" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            val reqDto = parseCreatePrintingQuoteRequest(request.body)
            val res = useCases.createPrintingQuote(principal, reqDto)
            HttpResponse(201, ApiSuccessResponse(data = res, correlationId = correlationId), correlationId)
        }

        request.path == "/api/v1/printing-quotes/calculate" && request.method == "POST" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            val reqDto = parseCalculatePrintingQuoteRequest(request.body)
            val res = useCases.calculatePrintingQuote(principal, reqDto)
            HttpResponse(200, ApiSuccessResponse(data = res, correlationId = correlationId), correlationId)
        }

        request.path == "/api/v1/printing-quotes/recalculate" && request.method == "POST" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            val reqDto = parseCalculatePrintingQuoteRequest(request.body)
            val res = useCases.recalculatePrintingQuote(principal, reqDto)
            HttpResponse(200, ApiSuccessResponse(data = res, correlationId = correlationId), correlationId)
        }

        request.path == "/api/v1/printing-quotes/review" && request.method == "POST" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            val reqDto = parseQuoteReviewRequest(request.body)
            val res = useCases.reviewPrintingQuote(principal, reqDto)
            HttpResponse(200, ApiSuccessResponse(data = res, correlationId = correlationId), correlationId)
        }

        request.path.matches(Regex("^/api/v1/printing-quotes/[^/]+/submit-review$")) && request.method == "POST" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            val id = request.path.removePrefix("/api/v1/printing-quotes/").removeSuffix("/submit-review")
            val res = useCases.submitPrintingQuoteForReview(principal, id)
            HttpResponse(200, ApiSuccessResponse(data = res, correlationId = correlationId), correlationId)
        }

        request.path.matches(Regex("^/api/v1/printing-quotes/[^/]+/reconcile$")) && request.method == "POST" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            val queryParams = parseQueryParams(request.path)
            val id = request.path.removePrefix("/api/v1/printing-quotes/").substringBefore("?").removeSuffix("/reconcile")
            val versionId = queryParams["versionId"] ?: (request.body as? Map<String, Any?>)?.get("versionId")?.toString() ?: ""
            val res = useCases.reconcilePrintingQuote(principal, id, versionId)
            HttpResponse(200, ApiSuccessResponse(data = res, correlationId = correlationId), correlationId)
        }

        request.path.matches(Regex("^/api/v1/printing-quotes/[^/]+/breakdown$")) && request.method == "GET" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            val versionId = request.path.removePrefix("/api/v1/printing-quotes/").removeSuffix("/breakdown")
            val res = useCases.getPrintingQuoteCostBreakdown(principal, versionId)
            HttpResponse(200, ApiSuccessResponse(data = res, correlationId = correlationId), correlationId)
        }

        request.path.matches(Regex("^/api/v1/printing-quotes/[^/]+/tiers$")) && request.method == "GET" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            val versionId = request.path.removePrefix("/api/v1/printing-quotes/").removeSuffix("/tiers")
            val res = useCases.getPrintingQuoteQuantityTiers(principal, versionId)
            HttpResponse(200, ApiSuccessResponse(data = res, correlationId = correlationId), correlationId)
        }

        request.path.matches(Regex("^/api/v1/printing-quotes/[^/]+/audit$")) && request.method == "GET" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            val id = request.path.removePrefix("/api/v1/printing-quotes/").removeSuffix("/audit")
            val res = useCases.getPrintingQuoteAuditTrail(principal, id)
            HttpResponse(200, ApiSuccessResponse(data = res, correlationId = correlationId), correlationId)
        }

        request.path.matches(Regex("^/api/v1/printing-quotes/[^/]+/handoff$")) && request.method == "GET" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            val id = request.path.removePrefix("/api/v1/printing-quotes/").removeSuffix("/handoff")
            val res = useCases.exportPrintingQuoteHandoffContract(principal, id)
            HttpResponse(200, ApiSuccessResponse(data = res, correlationId = correlationId), correlationId)
        }

        request.path.matches(Regex("^/api/v1/printing-quotes/[^/]+/versions$")) && request.method == "GET" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            val id = request.path.removePrefix("/api/v1/printing-quotes/").removeSuffix("/versions")
            val res = useCases.listPrintingQuoteVersions(principal, id)
            HttpResponse(200, ApiSuccessResponse(data = res, correlationId = correlationId), correlationId)
        }

        request.path.matches(Regex("^/api/v1/printing-quotes/versions/[^/]+$")) && request.method == "GET" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            val versionId = request.path.removePrefix("/api/v1/printing-quotes/versions/")
            val res = useCases.getPrintingQuoteVersion(principal, versionId)
            HttpResponse(200, ApiSuccessResponse(data = res, correlationId = correlationId), correlationId)
        }

        request.path.matches(Regex("^/api/v1/printing-quotes/[^/]+$")) && request.method == "GET" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            val id = request.path.removePrefix("/api/v1/printing-quotes/")
            val res = useCases.getPrintingQuote(principal, id)
            HttpResponse(200, ApiSuccessResponse(data = res, correlationId = correlationId), correlationId)
        }

        else -> null
    }

    // =========================================================================
    // MODULE 15 STEP 02: VENDOR PAYABLE REST ROUTES
    // =========================================================================

    private suspend fun handleVendorPayableRoutes(request: HttpRequest, correlationId: String): HttpResponse? = when {
        // --- Create Vendor Payable ---
        request.path == "/api/v1/vendor-payables" && request.method == "POST" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            val reqDto = when (val b = request.body) {
                is CreateVendorPayableRequest -> b
                is Map<*, *> -> CreateVendorPayableRequest(
                    vendorId = b["vendorId"]?.toString() ?: throw ValidationException("Missing vendorId"),
                    jobId = b["jobId"]?.toString(),
                    vendorJobId = b["vendorJobId"]?.toString(),
                    billReference = b["billReference"]?.toString(),
                    originalAmount = b["originalAmount"]?.toString() ?: throw ValidationException("Missing originalAmount"),
                    currency = b["currency"]?.toString() ?: "BDT",
                    issueDate = (b["issueDate"] as? Number)?.toLong(),
                    paymentTerms = b["paymentTerms"]?.toString() ?: "NET_30",
                    customTermDays = (b["customTermDays"] as? Number)?.toInt(),
                    description = b["description"]?.toString() ?: throw ValidationException("Missing description"),
                    notes = b["notes"]?.toString(),
                    attachmentUrl = b["attachmentUrl"]?.toString(),
                    idempotencyKey = b["idempotencyKey"]?.toString(),
                    autoSubmit = b["autoSubmit"] as? Boolean ?: false
                )
                else -> throw ValidationException("Request body must be a valid CreateVendorPayableRequest.")
            }
            val created = useCases.createVendorPayable(principal, reqDto)
            HttpResponse(201, ApiSuccessResponse(data = created, correlationId = correlationId), correlationId)
        }

        // --- List Vendor Payables ---
        (request.path == "/api/v1/vendor-payables" || request.path.startsWith("/api/v1/vendor-payables?")) && request.method == "GET" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            val queryParams = if (request.path.contains("?")) {
                request.path.substringAfter("?").split("&").mapNotNull {
                    val parts = it.split("=")
                    if (parts.size == 2) parts[0] to parts[1] else null
                }.toMap()
            } else emptyMap()

            val vendorId = queryParams["vendorId"]
            val statusStr = queryParams["status"]
            val jobId = queryParams["jobId"]
            val isOverdueOnly = queryParams["isOverdueOnly"]?.toBooleanStrictOrNull() ?: false
            val fromDate = queryParams["fromDate"]?.toLongOrNull()
            val toDate = queryParams["toDate"]?.toLongOrNull()
            val limit = queryParams["limit"]?.toIntOrNull() ?: 50
            val offset = queryParams["offset"]?.toIntOrNull() ?: 0

            val payables = useCases.listVendorPayables(
                principal = principal,
                vendorId = vendorId,
                statusStr = statusStr,
                jobId = jobId,
                isOverdueOnly = isOverdueOnly,
                fromDate = fromDate,
                toDate = toDate,
                limit = limit,
                offset = offset
            )
            HttpResponse(200, ApiSuccessResponse(data = payables, correlationId = correlationId), correlationId)
        }

        // --- Get Single Vendor Payable ---
        request.path.matches(Regex("^/api/v1/vendor-payables/[^/]+$")) && request.method == "GET" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            val payableId = request.path.substringAfter("/api/v1/vendor-payables/")
            val payable = useCases.getVendorPayable(principal, payableId)
            HttpResponse(200, ApiSuccessResponse(data = payable, correlationId = correlationId), correlationId)
        }

        // --- Update Vendor Payable Draft ---
        request.path.matches(Regex("^/api/v1/vendor-payables/[^/]+$")) && request.method == "PUT" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            val payableId = request.path.substringAfter("/api/v1/vendor-payables/")
            val reqDto = when (val b = request.body) {
                is UpdateVendorPayableRequest -> b
                is Map<*, *> -> UpdateVendorPayableRequest(
                    vendorId = b["vendorId"]?.toString(),
                    jobId = b["jobId"]?.toString(),
                    vendorJobId = b["vendorJobId"]?.toString(),
                    billReference = b["billReference"]?.toString(),
                    originalAmount = b["originalAmount"]?.toString(),
                    currency = b["currency"]?.toString(),
                    issueDate = (b["issueDate"] as? Number)?.toLong(),
                    paymentTerms = b["paymentTerms"]?.toString(),
                    customTermDays = (b["customTermDays"] as? Number)?.toInt(),
                    description = b["description"]?.toString(),
                    notes = b["notes"]?.toString(),
                    attachmentUrl = b["attachmentUrl"]?.toString()
                )
                else -> throw ValidationException("Request body must be a valid UpdateVendorPayableRequest.")
            }
            val updated = useCases.updateVendorPayableDraft(principal, payableId, reqDto)
            HttpResponse(200, ApiSuccessResponse(data = updated, correlationId = correlationId), correlationId)
        }

        // --- Submit Vendor Payable ---
        request.path.matches(Regex("^/api/v1/vendor-payables/[^/]+/submit$")) && request.method == "POST" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            val payableId = request.path.substringBefore("/submit").substringAfter("/api/v1/vendor-payables/")
            val submitted = useCases.submitVendorPayable(principal, payableId)
            HttpResponse(200, ApiSuccessResponse(data = submitted, correlationId = correlationId), correlationId)
        }

        // --- Approve Vendor Payable ---
        request.path.matches(Regex("^/api/v1/vendor-payables/[^/]+/approve$")) && request.method == "POST" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            val payableId = request.path.substringBefore("/approve").substringAfter("/api/v1/vendor-payables/")
            val reqDto = when (val b = request.body) {
                is ApproveVendorPayableRequest -> b
                is Map<*, *> -> ApproveVendorPayableRequest(notes = b["notes"]?.toString())
                null -> ApproveVendorPayableRequest()
                else -> throw ValidationException("Request body must be a valid ApproveVendorPayableRequest.")
            }
            val approved = useCases.approveVendorPayable(principal, payableId, reqDto)
            HttpResponse(200, ApiSuccessResponse(data = approved, correlationId = correlationId), correlationId)
        }

        // --- Reject Vendor Payable ---
        request.path.matches(Regex("^/api/v1/vendor-payables/[^/]+/reject$")) && request.method == "POST" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            val payableId = request.path.substringBefore("/reject").substringAfter("/api/v1/vendor-payables/")
            val reqDto = when (val b = request.body) {
                is RejectVendorPayableRequest -> b
                is Map<*, *> -> RejectVendorPayableRequest(reason = b["reason"]?.toString() ?: throw ValidationException("Missing rejection reason"))
                else -> throw ValidationException("Request body must be a valid RejectVendorPayableRequest.")
            }
            val rejected = useCases.rejectVendorPayable(principal, payableId, reqDto)
            HttpResponse(200, ApiSuccessResponse(data = rejected, correlationId = correlationId), correlationId)
        }

        // --- Cancel Vendor Payable ---
        request.path.matches(Regex("^/api/v1/vendor-payables/[^/]+/cancel$")) && request.method == "POST" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            val payableId = request.path.substringBefore("/cancel").substringAfter("/api/v1/vendor-payables/")
            val reqDto = when (val b = request.body) {
                is CancelVendorPayableRequest -> b
                is Map<*, *> -> CancelVendorPayableRequest(reason = b["reason"]?.toString() ?: throw ValidationException("Missing cancellation reason"))
                else -> throw ValidationException("Request body must be a valid CancelVendorPayableRequest.")
            }
            val cancelled = useCases.cancelVendorPayable(principal, payableId, reqDto)
            HttpResponse(200, ApiSuccessResponse(data = cancelled, correlationId = correlationId), correlationId)
        }

        // --- Void Vendor Payable ---
        request.path.matches(Regex("^/api/v1/vendor-payables/[^/]+/void$")) && request.method == "POST" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            val payableId = request.path.substringBefore("/void").substringAfter("/api/v1/vendor-payables/")
            val reqDto = when (val b = request.body) {
                is VoidVendorPayableRequest -> b
                is Map<*, *> -> VoidVendorPayableRequest(reason = b["reason"]?.toString() ?: throw ValidationException("Missing void reason"))
                else -> throw ValidationException("Request body must be a valid VoidVendorPayableRequest.")
            }
            val voided = useCases.voidVendorPayable(principal, payableId, reqDto)
            HttpResponse(200, ApiSuccessResponse(data = voided, correlationId = correlationId), correlationId)
        }

        // --- Allocate Payment ---
        request.path.matches(Regex("^/api/v1/vendor-payables/[^/]+/payments/allocate$")) && request.method == "POST" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            val payableId = request.path.substringBefore("/payments/allocate").substringAfter("/api/v1/vendor-payables/")
            val reqDto = when (val b = request.body) {
                is AllocateVendorPayablePaymentRequest -> b
                is Map<*, *> -> AllocateVendorPayablePaymentRequest(
                    amount = b["amount"]?.toString() ?: throw ValidationException("Missing amount"),
                    paymentMethod = b["paymentMethod"]?.toString() ?: "BANK",
                    paymentReference = b["paymentReference"]?.toString(),
                    paymentDate = (b["paymentDate"] as? Number)?.toLong(),
                    notes = b["notes"]?.toString(),
                    idempotencyKey = b["idempotencyKey"]?.toString()
                )
                else -> throw ValidationException("Request body must be a valid AllocateVendorPayablePaymentRequest.")
            }
            val allocated = useCases.allocateVendorPayablePayment(principal, payableId, reqDto)
            HttpResponse(200, ApiSuccessResponse(data = allocated, correlationId = correlationId), correlationId)
        }

        // --- Get Allocations for Payable ---
        request.path.matches(Regex("^/api/v1/vendor-payables/[^/]+/payments$")) && request.method == "GET" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            val payableId = request.path.substringBefore("/payments").substringAfter("/api/v1/vendor-payables/")
            val allocations = useCases.getVendorPayablePaymentAllocations(principal, payableId)
            HttpResponse(200, ApiSuccessResponse(data = allocations, correlationId = correlationId), correlationId)
        }

        // --- Get Audit Trail for Payable ---
        request.path.matches(Regex("^/api/v1/vendor-payables/[^/]+/audit$")) && request.method == "GET" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            val payableId = request.path.substringBefore("/audit").substringAfter("/api/v1/vendor-payables/")
            val audits = useCases.getVendorPayableAuditTrail(principal, payableId)
            HttpResponse(200, ApiSuccessResponse(data = audits, correlationId = correlationId), correlationId)
        }

        // --- Get Vendor Payable Summary ---
        request.path.matches(Regex("^/api/v1/vendors/[^/]+/payables/summary$")) && request.method == "GET" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            val vendorId = request.path.substringBefore("/payables/summary").substringAfter("/api/v1/vendors/")
            val summary = useCases.getVendorPayableSummary(principal, vendorId)
            HttpResponse(200, ApiSuccessResponse(data = summary, correlationId = correlationId), correlationId)
        }

        // --- Get Vendor Payable Aging ---
        (request.path.matches(Regex("^/api/v1/vendors/[^/]+/payables/aging.*$")) || request.path == "/api/v1/vendor-payables/aging" || request.path.startsWith("/api/v1/vendor-payables/aging?")) && request.method == "GET" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            val vendorId = if (request.path.startsWith("/api/v1/vendors/")) {
                request.path.substringBefore("/payables/aging").substringAfter("/api/v1/vendors/")
            } else null

            val queryParams = if (request.path.contains("?")) {
                request.path.substringAfter("?").split("&").mapNotNull {
                    val parts = it.split("=")
                    if (parts.size == 2) parts[0] to parts[1] else null
                }.toMap()
            } else emptyMap()

            val asOfDate = queryParams["asOfDate"]?.toLongOrNull() ?: System.currentTimeMillis()
            val aging = useCases.getVendorPayableAging(principal, vendorId, asOfDate)
            HttpResponse(200, ApiSuccessResponse(data = aging, correlationId = correlationId), correlationId)
        }


        // ==========================================
        // MODULE 17 STEP 02 - PRINTING QUOTATION
        // ==========================================

        request.path == "/api/v1/printing-quotes" && request.method == "POST" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            val reqDto = parseCreatePrintingQuoteRequest(request.body)
            val res = useCases.createPrintingQuote(principal, reqDto)
            HttpResponse(201, ApiSuccessResponse(data = res, correlationId = correlationId), correlationId)
        }

        request.path == "/api/v1/printing-quotes/calculate" && request.method == "POST" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            val reqDto = parseCalculatePrintingQuoteRequest(request.body)
            val res = useCases.calculatePrintingQuote(principal, reqDto)
            HttpResponse(200, ApiSuccessResponse(data = res, correlationId = correlationId), correlationId)
        }

        request.path == "/api/v1/printing-quotes/recalculate" && request.method == "POST" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            val reqDto = parseCalculatePrintingQuoteRequest(request.body)
            val res = useCases.recalculatePrintingQuote(principal, reqDto)
            HttpResponse(200, ApiSuccessResponse(data = res, correlationId = correlationId), correlationId)
        }

        request.path == "/api/v1/printing-quotes/review" && request.method == "POST" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            val reqDto = parseQuoteReviewRequest(request.body)
            val res = useCases.reviewPrintingQuote(principal, reqDto)
            HttpResponse(200, ApiSuccessResponse(data = res, correlationId = correlationId), correlationId)
        }

        request.path.matches(Regex("^/api/v1/printing-quotes/[^/]+/submit-review$")) && request.method == "POST" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            val id = request.path.removePrefix("/api/v1/printing-quotes/").removeSuffix("/submit-review")
            val res = useCases.submitPrintingQuoteForReview(principal, id)
            HttpResponse(200, ApiSuccessResponse(data = res, correlationId = correlationId), correlationId)
        }

        request.path.matches(Regex("^/api/v1/printing-quotes/[^/]+/reconcile$")) && request.method == "POST" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            val queryParams = parseQueryParams(request.path)
            val id = request.path.removePrefix("/api/v1/printing-quotes/").substringBefore("?").removeSuffix("/reconcile")
            val versionId = queryParams["versionId"] ?: (request.body as? Map<String, Any?>)?.get("versionId")?.toString() ?: ""
            val res = useCases.reconcilePrintingQuote(principal, id, versionId)
            HttpResponse(200, ApiSuccessResponse(data = res, correlationId = correlationId), correlationId)
        }

        request.path.matches(Regex("^/api/v1/printing-quotes/[^/]+/breakdown$")) && request.method == "GET" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            val versionId = request.path.removePrefix("/api/v1/printing-quotes/").removeSuffix("/breakdown")
            val res = useCases.getPrintingQuoteCostBreakdown(principal, versionId)
            HttpResponse(200, ApiSuccessResponse(data = res, correlationId = correlationId), correlationId)
        }

        request.path.matches(Regex("^/api/v1/printing-quotes/[^/]+/tiers$")) && request.method == "GET" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            val versionId = request.path.removePrefix("/api/v1/printing-quotes/").removeSuffix("/tiers")
            val res = useCases.getPrintingQuoteQuantityTiers(principal, versionId)
            HttpResponse(200, ApiSuccessResponse(data = res, correlationId = correlationId), correlationId)
        }

        request.path.matches(Regex("^/api/v1/printing-quotes/[^/]+/audit$")) && request.method == "GET" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            val id = request.path.removePrefix("/api/v1/printing-quotes/").removeSuffix("/audit")
            val res = useCases.getPrintingQuoteAuditTrail(principal, id)
            HttpResponse(200, ApiSuccessResponse(data = res, correlationId = correlationId), correlationId)
        }

        request.path.matches(Regex("^/api/v1/printing-quotes/[^/]+/handoff$")) && request.method == "GET" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            val id = request.path.removePrefix("/api/v1/printing-quotes/").removeSuffix("/handoff")
            val res = useCases.exportPrintingQuoteHandoffContract(principal, id)
            HttpResponse(200, ApiSuccessResponse(data = res, correlationId = correlationId), correlationId)
        }

        request.path.matches(Regex("^/api/v1/printing-quotes/[^/]+/versions$")) && request.method == "GET" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            val id = request.path.removePrefix("/api/v1/printing-quotes/").removeSuffix("/versions")
            val res = useCases.listPrintingQuoteVersions(principal, id)
            HttpResponse(200, ApiSuccessResponse(data = res, correlationId = correlationId), correlationId)
        }

        request.path.matches(Regex("^/api/v1/printing-quotes/versions/[^/]+$")) && request.method == "GET" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            val versionId = request.path.removePrefix("/api/v1/printing-quotes/versions/")
            val res = useCases.getPrintingQuoteVersion(principal, versionId)
            HttpResponse(200, ApiSuccessResponse(data = res, correlationId = correlationId), correlationId)
        }

        request.path.matches(Regex("^/api/v1/printing-quotes/[^/]+$")) && request.method == "GET" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            val id = request.path.removePrefix("/api/v1/printing-quotes/")
            val res = useCases.getPrintingQuote(principal, id)
            HttpResponse(200, ApiSuccessResponse(data = res, correlationId = correlationId), correlationId)
        }

        else -> null
    }

    // =========================================================================
    // MODULE 15 STEP 03: BUSINESS LEDGER, FINANCIAL POSTING & COST ALLOCATION
    // =========================================================================

    private suspend fun handleBusinessLedgerRoutes(request: HttpRequest, correlationId: String): HttpResponse? = when {
        // --- Post Approved Expense ---
        request.path == "/api/v1/business-ledger/post-expense" && request.method == "POST" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            val reqDto = when (val b = request.body) {
                is PostApprovedExpenseRequest -> b
                is Map<*, *> -> PostApprovedExpenseRequest(
                    expenseId = b["expenseId"]?.toString() ?: throw ValidationException("Missing expenseId"),
                    accountCategory = b["accountCategory"]?.toString(),
                    description = b["description"]?.toString(),
                    reference = b["reference"]?.toString(),
                    jobId = b["jobId"]?.toString(),
                    idempotencyKey = b["idempotencyKey"]?.toString(),
                    correlationId = b["correlationId"]?.toString()
                )
                else -> throw ValidationException("Request body must be a valid PostApprovedExpenseRequest.")
            }
            val posted = useCases.postApprovedExpense(principal, reqDto)
            HttpResponse(201, ApiSuccessResponse(data = posted, correlationId = correlationId), correlationId)
        }

        // --- Post Approved Payable ---
        request.path == "/api/v1/business-ledger/post-payable" && request.method == "POST" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            val reqDto = when (val b = request.body) {
                is PostApprovedPayableRequest -> b
                is Map<*, *> -> PostApprovedPayableRequest(
                    payableId = b["payableId"]?.toString() ?: throw ValidationException("Missing payableId"),
                    accountCategory = b["accountCategory"]?.toString(),
                    description = b["description"]?.toString(),
                    reference = b["reference"]?.toString(),
                    jobId = b["jobId"]?.toString(),
                    idempotencyKey = b["idempotencyKey"]?.toString(),
                    correlationId = b["correlationId"]?.toString()
                )
                else -> throw ValidationException("Request body must be a valid PostApprovedPayableRequest.")
            }
            val posted = useCases.postApprovedPayable(principal, reqDto)
            HttpResponse(201, ApiSuccessResponse(data = posted, correlationId = correlationId), correlationId)
        }

        // --- Post Vendor Payment ---
        request.path == "/api/v1/business-ledger/post-vendor-payment" && request.method == "POST" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            val reqDto = when (val b = request.body) {
                is PostVendorPaymentRequest -> b
                is Map<*, *> -> PostVendorPaymentRequest(
                    payableId = b["payableId"]?.toString() ?: throw ValidationException("Missing payableId"),
                    allocationId = b["allocationId"]?.toString() ?: throw ValidationException("Missing allocationId"),
                    amount = b["amount"]?.toString() ?: throw ValidationException("Missing amount"),
                    currency = b["currency"]?.toString() ?: "BDT",
                    paymentDate = (b["paymentDate"] as? Number)?.toLong(),
                    paymentMethod = b["paymentMethod"]?.toString(),
                    paymentReference = b["paymentReference"]?.toString(),
                    accountCategory = b["accountCategory"]?.toString(),
                    description = b["description"]?.toString(),
                    idempotencyKey = b["idempotencyKey"]?.toString(),
                    correlationId = b["correlationId"]?.toString()
                )
                else -> throw ValidationException("Request body must be a valid PostVendorPaymentRequest.")
            }
            val posted = useCases.postVendorPayment(principal, reqDto)
            HttpResponse(201, ApiSuccessResponse(data = posted, correlationId = correlationId), correlationId)
        }

        // --- Post Business Adjustment ---
        request.path == "/api/v1/business-ledger/post-adjustment" && request.method == "POST" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            val reqDto = when (val b = request.body) {
                is PostBusinessAdjustmentRequest -> b
                is Map<*, *> -> PostBusinessAdjustmentRequest(
                    amount = b["amount"]?.toString() ?: throw ValidationException("Missing amount"),
                    isDebit = b["isDebit"] as? Boolean ?: true,
                    accountCategory = b["accountCategory"]?.toString() ?: throw ValidationException("Missing accountCategory"),
                    description = b["description"]?.toString() ?: throw ValidationException("Missing description"),
                    reference = b["reference"]?.toString(),
                    jobId = b["jobId"]?.toString(),
                    vendorId = b["vendorId"]?.toString(),
                    currency = b["currency"]?.toString() ?: "BDT",
                    idempotencyKey = b["idempotencyKey"]?.toString(),
                    correlationId = b["correlationId"]?.toString()
                )
                else -> throw ValidationException("Request body must be a valid PostBusinessAdjustmentRequest.")
            }
            val posted = useCases.postBusinessAdjustment(principal, reqDto)
            HttpResponse(201, ApiSuccessResponse(data = posted, correlationId = correlationId), correlationId)
        }

        // --- Reverse Posting ---
        request.path.matches(Regex("^/api/v1/business-ledger/[^/]+/reverse$")) && request.method == "POST" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            val postingId = request.path.substringBefore("/reverse").substringAfter("/api/v1/business-ledger/")
            val reqDto = when (val b = request.body) {
                is ReversePostingRequest -> b
                is Map<*, *> -> ReversePostingRequest(
                    reason = b["reason"]?.toString() ?: throw ValidationException("Missing reversal reason"),
                    correlationId = b["correlationId"]?.toString()
                )
                else -> throw ValidationException("Request body must be a valid ReversePostingRequest.")
            }
            val reversed = useCases.reverseBusinessLedgerPosting(principal, postingId, reqDto)
            HttpResponse(200, ApiSuccessResponse(data = reversed, correlationId = correlationId), correlationId)
        }

        // --- Get Business Ledger Balance ---
        (request.path == "/api/v1/business-ledger/balance" || request.path.startsWith("/api/v1/business-ledger/balance?")) && request.method == "GET" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            val queryParams = if (request.path.contains("?")) {
                request.path.substringAfter("?").split("&").mapNotNull {
                    val parts = it.split("=")
                    if (parts.size == 2) parts[0] to parts[1] else null
                }.toMap()
            } else emptyMap()
            val asOf = queryParams["asOf"]?.toLongOrNull() ?: System.currentTimeMillis()
            val balance = useCases.getBusinessLedgerBalance(principal, asOf)
            HttpResponse(200, ApiSuccessResponse(data = balance, correlationId = correlationId), correlationId)
        }

        // --- Get Business Ledger Period Summary ---
        (request.path == "/api/v1/business-ledger/period" || request.path.startsWith("/api/v1/business-ledger/period?")) && request.method == "GET" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            val queryParams = if (request.path.contains("?")) {
                request.path.substringAfter("?").split("&").mapNotNull {
                    val parts = it.split("=")
                    if (parts.size == 2) parts[0] to parts[1] else null
                }.toMap()
            } else emptyMap()
            val fromDate = queryParams["fromDate"]?.toLongOrNull() ?: 0L
            val toDate = queryParams["toDate"]?.toLongOrNull() ?: System.currentTimeMillis()
            val summary = useCases.getBusinessLedgerPeriod(principal, fromDate, toDate)
            HttpResponse(200, ApiSuccessResponse(data = summary, correlationId = correlationId), correlationId)
        }

        // --- Get Business Ledger Audit Trail ---
        (request.path == "/api/v1/business-ledger/audit" || request.path.startsWith("/api/v1/business-ledger/audit?")) && request.method == "GET" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            val queryParams = if (request.path.contains("?")) {
                request.path.substringAfter("?").split("&").mapNotNull {
                    val parts = it.split("=")
                    if (parts.size == 2) parts[0] to parts[1] else null
                }.toMap()
            } else emptyMap()
            val sourceId = queryParams["sourceId"]
            val postingId = queryParams["postingId"]
            val allocationId = queryParams["allocationId"]
            val audits = useCases.getBusinessLedgerAuditTrail(principal, sourceId, postingId, allocationId)
            HttpResponse(200, ApiSuccessResponse(data = audits, correlationId = correlationId), correlationId)
        }

        // --- Get Business Ledger Postings by Source ---
        request.path.matches(Regex("^/api/v1/business-ledger/source/[^/]+/[^/]+$")) && request.method == "GET" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            val segments = request.path.removePrefix("/api/v1/business-ledger/source/").split("/")
            val sourceType = segments[0]
            val sourceId = segments[1]
            val postings = useCases.getBusinessLedgerPostingsBySource(principal, sourceType, sourceId)
            HttpResponse(200, ApiSuccessResponse(data = postings, correlationId = correlationId), correlationId)
        }

        // --- Get Single Business Ledger Posting ---
        request.path.matches(Regex("^/api/v1/business-ledger/[^/]+$")) &&
        request.method == "GET" &&
        !request.path.endsWith("/balance") &&
        !request.path.endsWith("/period") &&
        !request.path.endsWith("/audit") &&
        !request.path.endsWith("/summary") -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            val postingId = request.path.substringAfter("/api/v1/business-ledger/")
            val posting = useCases.getBusinessLedgerPosting(principal, postingId)
            HttpResponse(200, ApiSuccessResponse(data = posting, correlationId = correlationId), correlationId)
        }

        // --- List Business Ledger Postings ---
        (request.path == "/api/v1/business-ledger" || request.path.startsWith("/api/v1/business-ledger?")) && request.method == "GET" -> {
