            val reqDto = request.body as? ResolveAlertRequestDto ?: ResolveAlertRequestDto()
            val alert = useCases.resolveGovernanceAlert(principal, alertId, reqDto)
            HttpResponse(200, ApiSuccessResponse(data = alert, correlationId = correlationId), correlationId)
        }

        // 23. Dismiss Alert
        request.path.startsWith("/api/v1/business-financial-governance/alerts/") && request.path.endsWith("/dismiss") && request.method == "POST" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            val alertId = request.path.removePrefix("/api/v1/business-financial-governance/alerts/").removeSuffix("/dismiss")
