            val alert = useCases.dismissGovernanceAlert(principal, alertId, reqDto)
            HttpResponse(200, ApiSuccessResponse(data = alert, correlationId = correlationId), correlationId)
        }

        // 24. List Governance Audit Events
        (request.path == "/api/v1/business-financial-governance/audit" || request.path.startsWith("/api/v1/business-financial-governance/audit?")) && request.method == "GET" -> {
