        (request.path.startsWith("/api/v1/business-financial-integrity/module16-handoff")) && request.method == "GET" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            val queryParams = parseQueryParams(request.path)
            val periodId = if (request.path.contains("?")) {
