    // =========================================================================
    // MODULE 16: PROFITABILITY & COST ANALYSIS ENGINE ROUTES
    // =========================================================================

    private suspend fun handleProfitabilityAnalysisRoutes(request: HttpRequest, correlationId: String): HttpResponse? = when {
        // --- Module 16 Step 01: Profit & Cost Analysis Foundation & Financial Handoff ---

        request.path == "/api/v1/profit-cost-analysis/snapshots" && request.method == "POST" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            val body = (request.body as? Map<*, *>) ?: emptyMap<String, Any>()
            val reqDto = com.sucharu.sucharupro.data.api.model.profitability.GenerateProfitabilitySnapshotRequestDto(
                scope = body["scope"] as? String ?: "BUSINESS",
                targetEntityId = body["targetEntityId"] as? String,
                periodId = body["periodId"] as? String,
                currency = body["currency"] as? String ?: "BDT",
                customRevenue = (body["customRevenue"] as? Number)?.toString()?.let { java.math.BigDecimal(it) },
                customDirectCost = (body["customDirectCost"] as? Number)?.toString()?.let { java.math.BigDecimal(it) },
                customIndirectCost = (body["customIndirectCost"] as? Number)?.toString()?.let { java.math.BigDecimal(it) },
                baselineCost = (body["baselineCost"] as? Number)?.toString()?.let { java.math.BigDecimal(it) },
                baselineRevenue = (body["baselineRevenue"] as? Number)?.toString()?.let { java.math.BigDecimal(it) },
                idempotencyKey = body["idempotencyKey"] as? String
            )
            val res = useCases.generateProfitabilitySnapshot(principal, reqDto)
            HttpResponse(201, ApiSuccessResponse(data = res, correlationId = correlationId), correlationId)
        }

        request.path.matches(Regex("^/api/v1/profit-cost-analysis/snapshots/[^/]+$")) && request.method == "GET" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            val id = request.path.substringAfter("/api/v1/profit-cost-analysis/snapshots/")
            val res = useCases.getProfitabilitySnapshot(principal, id)
            HttpResponse(200, ApiSuccessResponse(data = res, correlationId = correlationId), correlationId)
        }

        (request.path == "/api/v1/profit-cost-analysis/snapshots" || request.path.startsWith("/api/v1/profit-cost-analysis/snapshots?")) && request.method == "GET" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            val queryParams = parseQueryParams(request.path)
            val list = useCases.listProfitabilitySnapshots(
                principal = principal,
                scope = queryParams["scope"],
                targetEntityId = queryParams["targetEntityId"],
                periodId = queryParams["periodId"],
                limit = queryParams["limit"]?.toIntOrNull() ?: 100,
                offset = queryParams["offset"]?.toIntOrNull() ?: 0
