            val res = useCases.reconcileProfitabilitySnapshot(principal, snapshotId)
            HttpResponse(200, ApiSuccessResponse(data = res, correlationId = correlationId), correlationId)
        }

        (request.path == "/api/v1/profit-cost-analysis/reconciliations" || request.path.startsWith("/api/v1/profit-cost-analysis/reconciliations?")) && request.method == "GET" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
