        request.path.startsWith("/api/v1/profit-cost-analysis/jobs/") && (request.path.endsWith("/actual-cost") || request.path.contains("/actual-cost?")) && request.method == "GET" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
