    private suspend fun handleVendorProfitabilityRoutes(request: HttpRequest, correlationId: String): HttpResponse? = when {
        request.path.matches(Regex("/api/v1/profit-cost-analysis/vendors/[^/]+/profitability/calculate")) && request.method == "POST" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
            val vendorId = request.path.split("/")[5]
            val body = request.body as? Map<String, Any?> ?: emptyMap()
            val reqDto = CalculateVendorProfitabilityRequestDto(
                vendorName = body["vendorName"] as? String,
                vendorCode = body["vendorCode"] as? String,
                serviceCategory = body["serviceCategory"] as? String,
                periodId = body["periodId"] as? String,
                periodStart = (body["periodStart"] as? Number)?.toLong(),
                periodEnd = (body["periodEnd"] as? Number)?.toLong(),
                customBaselineCost = (body["customBaselineCost"] as? Number)?.toDouble()?.let { java.math.BigDecimal.valueOf(it) },
                idempotencyKey = body["idempotencyKey"] as? String
            )
            val res = useCases.calculateVendorProfitability(principal, vendorId, reqDto)
            HttpResponse(200, ApiSuccessResponse(data = res, correlationId = correlationId), correlationId)
        }

        request.path.matches(Regex("/api/v1/profit-cost-analysis/vendors/[^/]+/profitability/components")) && request.method == "GET" -> {
            val principal = securityContext.authenticate(request.authorizationHeader)
