private fun parseQueryParams(path: String): Map<String, String> {
    if (!path.contains("?")) return emptyMap()
    return path.substringAfter("?").split("&").mapNotNull {
        val parts = it.split("=")
        if (parts.size == 2) parts[0] to parts[1] else null
    }.toMap()
}










